window.OSCE_STRATEGY = [{"id": "newrx", "label": "New Prescription Counselling", "framework": "SAILS", "steps": ["Introduce yourself, confirm patient identity (name + DOB), and check privacy/consent to counsel.", "Store what they already know — ask what the prescriber told them about the diagnosis and medication (avoid repeating what they already understand).", "Action — explain in plain language what the drug does and why it was prescribed for them specifically.", "Instructions — how to take it (dose, timing, food/interactions), and what to do if a dose is missed.", "Life effects — expected side effects, how to manage minor ones, and what's serious enough to report.", "Seek help — red flags, when to call the pharmacy vs. seek urgent care, and confirm follow-up (labs, refill timing)."], "pitfalls": ["Reciting a monograph instead of tailoring to what the patient already knows", "Missing the ONE interaction or monitoring point that's the actual point of the station (e.g., levothyroxine + calcium, metformin + contrast dye)", "Forgetting to check understanding (teach-back) before closing"]}, {"id": "otc", "label": "OTC / Self-Care Triage", "framework": "WWHAM / ASMETHOD", "steps": ["Clarify who the product is for and confirm you're speaking with (or about) the right person.", "Who — age, pregnancy/breastfeeding status if relevant. What — symptoms, onset, duration, character. Action taken already. Medication history (Rx, OTC, herbals) and allergies.", "Actively screen for red flags/exclusions for self-treatment before recommending anything (duration too long, red-flag symptom, high-risk population, interacting current therapy).", "If self-care is appropriate: recommend a specific product/class, dose, and duration, with a clear stop-and-see-a-doctor point.", "If NOT appropriate for self-care: explain why in plain language and refer, without simply refusing."], "pitfalls": ["Jumping straight to a product recommendation before finishing the assessment", "Missing a red flag buried in the stem (e.g., cough duration, chest pain, unexplained weight loss)", "Recommending a product that interacts with a medication mentioned earlier in the stem"]}, {"id": "adr", "label": "Adverse Drug Reaction Report", "framework": "Assess → Severity → Act → Follow-up", "steps": ["Introduce yourself and gather the details: onset, timeline relative to the suspected drug, severity, and associated symptoms.", "Actively rule in/out the serious version of the reaction (e.g., dark urine + myopathy = possible rhabdomyolysis; not just 'sore muscles').", "Decide and state urgency clearly — stop the drug now vs. continue and monitor vs. this is expected/benign and self-limiting.", "Explain next steps: what testing is needed, whether to go to urgent care/ER today, and what alternative therapy might follow.", "Document and communicate with the prescriber; close the loop with the patient on what happens next."], "pitfalls": ["Reassuring the patient before confirming the reaction isn't dangerous", "Failing to explicitly say 'stop the drug' when that's the correct action", "Not identifying the single red-flag detail the case is testing (a lab value, a symptom pairing)"]}, {"id": "adherence", "label": "Non-Adherence / Motivational Interviewing", "framework": "Explore → Acknowledge → Inform → Collaborate → Follow-up (OARS)", "steps": ["Build rapport; open with an open-ended, non-judgmental question about how things have been going with the medication.", "Explore their reasons/beliefs/barriers without arguing or lecturing — use reflective listening.", "Acknowledge their perspective as valid before providing information (avoid 'yes, but...').", "Inform: give the missing clinical information (the risk they're underestimating) briefly and only once rapport is established.", "Collaborate on a concrete next step that respects their autonomy (dose change, reminder tool, follow-up visit) — don't issue ultimatums."], "pitfalls": ["Lecturing or scolding, which shuts down disclosure", "Assuming the barrier is knowledge when it's often cost, side effects, or beliefs", "Ending without one specific, agreed-upon next action"]}, {"id": "prescribercall", "label": "Prescriber Call", "framework": "SBAR", "steps": ["Introduce yourself and your pharmacy clearly, and state the reason for the call up front.", "Situation — the immediate issue in one sentence.", "Background — relevant patient history, labs, current therapy.", "Assessment — your clinical concern, stated specifically (not vague 'just checking').", "Recommendation — a concrete proposed action or alternative, not just a flagged problem.", "Confirm the plan, who follows up with the patient, and document the call."], "pitfalls": ["Presenting the problem without a recommendation", "Being vague about the actual clinical concern (say the number/threshold, not just 'the labs look off')", "Sounding confrontational instead of collaborative"]}, {"id": "refusal", "label": "Refusal / Regulatory Conflict", "framework": "Empathize → Explain → Explore safety → Offer alternative", "steps": ["Listen fully and respond with empathy before explaining any policy or legal constraint.", "Clearly explain the regulatory/professional reason you cannot do what's being asked, in plain non-accusatory language.", "Sensitively screen for safety concerns (withdrawal, diversion, pain crisis) without being accusatory.", "Offer a concrete alternative path forward (contacting the prescriber, an interim plan, a same-day appointment).", "Document the interaction thoroughly and close respectfully."], "pitfalls": ["Leading with a flat 'no' before any empathy or explanation", "Being accusatory toward a patient who may have a legitimate reason", "Failing to offer any alternative or next step"]}, {"id": "immunization", "label": "Immunization Screening & Counselling", "framework": "Screen → Consent → Administer counsel → Aftercare", "steps": ["Confirm identity, indication, and eligibility (age, interval since last dose, catch-up schedule if relevant).", "Screen contraindications/precautions: anaphylaxis to a prior dose or vaccine component, current acute illness, immunosuppression, pregnancy status if relevant to that vaccine.", "Obtain informed consent — explain the vaccine, common local/systemic reactions, and rare serious reactions in balanced, non-alarming language.", "Discuss same-day co-administration rules and timing with other vaccines/medications if relevant.", "Aftercare: observation period (typically 15 minutes), how to manage soreness/fever, and when to seek care (anaphylaxis signs)."], "pitfalls": ["Missing a contraindication buried in the patient's stated allergy history", "Forgetting the post-injection observation period", "Not documenting/reporting per the provincial immunization program"]}, {"id": "calculation", "label": "In-Station Calculation", "framework": "Extract → Set up → Solve → Sanity-check → State", "steps": ["Extract only the numbers/units you actually need from the stem; ignore distractor data.", "Set up the equation explicitly (write out units) before calculating — this is what earns partial marks and catches unit errors.", "Solve carefully, watching for unit conversions (mg vs. mcg, mL vs. L, mmol vs. mg).", "Sanity-check: does the final number make clinical/physical sense (e.g., a pediatric dose shouldn't exceed the adult max)?", "State the final answer clearly with correct units, and briefly explain your reasoning to the examiner."], "pitfalls": ["Skipping unit conversions (a classic trap: mcg/kg vs mg/kg, %w/v vs %w/w)", "Not showing work, so a small arithmetic slip loses all marks instead of partial credit", "Failing to sanity-check an answer that's clinically implausible"]}, {"id": "error", "label": "Medication Error Disclosure", "framework": "Acknowledge → Apologize → Assess harm → Act → Prevent", "steps": ["Acknowledge the error directly and honestly as soon as it is identified — do not minimize or deflect.", "Apologize sincerely without excessive self-blame or panic that alarms the patient unnecessarily.", "Assess actual/potential harm from the specific error (wrong drug, wrong dose, wrong patient) and give clear clinical guidance on what to do now.", "Act: correct the error, notify the prescriber if needed, and document per the pharmacy's incident-reporting process.", "Prevent: briefly note what will change to reduce recurrence (double-check process, systems fix) without being defensive."], "pitfalls": ["Being defensive or blaming a colleague/system in front of the patient", "Failing to give a clear clinical instruction (what to actually do about the error) alongside the apology", "Forgetting to mention documentation/incident reporting"]}, {"id": "assessment", "label": "Patient Assessment / History-Taking", "framework": "OPQRST + PMH/SH + red-flag screen", "steps": ["Onset, Provocation/Palliation, Quality, Region/Radiation, Severity, Timing of the presenting complaint.", "Past medical history, current medications (Rx/OTC/herbal), allergies, and relevant social history (travel, occupation, lifestyle).", "Actively screen for red flags specific to the presentation before considering self-care or minor-ailment prescribing.", "State a working assessment and plan, including whether this is within your scope to manage or needs referral.", "Explain the plan and safety-net advice to the patient in plain language."], "pitfalls": ["Skipping red-flag screening because the case initially sounds routine", "Not asking about travel history when relevant to infectious/tropical presentations", "Failing to state a clear plan at the end, even after gathering good history"]}, {"id": "difficult", "label": "Difficult Conversation", "framework": "Listen → Validate → Provide facts → Support → Plan", "steps": ["Let the person speak fully before responding; resist the urge to jump straight to facts or solutions.", "Validate the emotion in the room explicitly ('that sounds really frustrating/scary') before anything else.", "Provide accurate, balanced information only once the emotional temperature has come down.", "Offer support resources appropriate to the situation (counselling, social work, patient organizations, MAiD-adjacent conversations require particular sensitivity and scope-of-practice awareness).", "Close with a concrete next step and an open door for further questions."], "pitfalls": ["Rushing to 'fix' the conversation with facts before validating emotion", "Overstepping scope of practice on sensitive topics (e.g., MAiD) instead of validating and appropriately referring", "Sounding rehearsed/scripted rather than present with the patient"]}, {"id": "screen-rx", "label": "Screening New Prescriptions (non-interactive)", "framework": "Read → Cross-check → Flag → Specify", "steps": ["Read each written prescription fully before judging it — drug, strength, sig, quantity, prescriber, and patient.", "Cross-check against what you know: is the dose/frequency appropriate for the indication and patient? Is anything missing (strength, directions, quantity, indication for an ambiguous drug)?", "Check for legal/technical completeness: is it written for one patient only, is age-appropriate, is the drug appropriate for that age group.", "If everything is complete and appropriate, mark 'NO problem(s)' — do not invent a problem that isn't there.", "If there is a problem, write the SPECIFIC issue in a few words (e.g. 'no directions specified', not just 'incomplete') — vague answers are marked wrong even if you spotted the right prescription."], "pitfalls": ["Describing the problem too vaguely to be scored (state exactly what's wrong)", "Missing a prescription that has no problem at all — not every item is a trap", "Spending too long on one prescription and running out of time for the rest"]}, {"id": "check-meds", "label": "Checking Prepared Medications (non-interactive)", "framework": "Compare → Verify → Specify the fix", "steps": ["Compare the prepared medication label word-for-word against the written prescription: patient name, drug, strength, directions, quantity.", "Assume the prescription itself is correct and already resolved — you are only checking that what was PREPARED matches what was PRESCRIBED.", "If a correction is needed, state the actual fix required (e.g. 'change label directions to 5 mL twice daily'), not just a description of the error (e.g. NOT 'wrong directions').", "Ignore auxiliary labels unless the station instructions say otherwise — focus on what's explicitly asked.", "If everything matches, mark 'NO correction(s) required' — don't manufacture an error."], "pitfalls": ["Stating what's wrong instead of the specific correction needed (this is marked incorrect)", "Correcting something outside the scope given (e.g. auxiliary labels when told not to consider them)", "Assuming a prescription error exists when the task says to assume prescriptions are already correct"]}];

window.OSCE_STATIONS = [{"id": "o1", "ti": "New Prescription: Metformin", "tl": 7, "type": "newrx", "sc": "Mr. David Chen, 55, is picking up his first prescription for metformin 500 mg PO BID, newly diagnosed with type 2 diabetes. He tells the technician he's worried about “the sugar pill making him gain weight.”", "ta": "Counsel Mr. Chen on his new metformin prescription.", "cl": ["Introduces self and confirms patient identity (name + DOB)", "Asks what the physician told him about the medication and diagnosis", "Screens for allergies, other medications (incl. OTC/herbals), and renal/liver history", "Explains action in plain language (helps the body use its own insulin; does not typically cause weight gain)", "Explains instructions — take with food to reduce GI upset; may be titrated over time", "Covers expected side effects (transient GI upset) and rare serious risk (lactic acidosis) without alarming him", "Advises holding metformin around IV contrast dye studies or surgery", "Gives red flags (severe vomiting, unusual muscle pain, difficulty breathing) and monitoring plan (A1C q3 months)", "Checks understanding, invites questions, closes with follow-up"], "mn": "Framework: SAILS — Store, Action, Instructions, Life effects, Seek help.", "format": "patient", "objectives": ["To counsel a patient on a new prescription for a chronic disease medication.", "To address the patient's misconceptions about how the medication works."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come to the counter to pick up a new prescription. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "David Wei Chen", "gender": "Male", "age": 55, "behaviour": "Polite but visibly skeptical about starting a new medication.", "profile": ["Allergies: None known", "Medical History: Newly diagnosed type 2 diabetes mellitus; overweight (BMI 29)", "Current Medications: Metformin 500 mg PO BID (new); no other regular medications", "Social History: Works as an accountant; sedentary lifestyle; drinks 2-3 coffees daily"], "otherInfo": ["His doctor mentioned an A1C of 7.8% at diagnosis but he doesn't fully understand what that means.", "His father takes many pills for diabetes and had a leg amputation, which frightens him.", "He has not changed his diet or started exercising yet because he 'doesn't have time.'", "He heard from a coworker that metformin causes diarrhea and is anxious about that.", "He is scheduled for a CT scan with contrast dye in three weeks for an unrelated issue.", "He takes an occasional ibuprofen for headaches but nothing else regularly."], "openingLine": "Hi, I'm here to pick up this metformin, but honestly I'm not sure I want to start it — my coworker said it's the 'sugar pill' that makes you fat. Is that true?", "responses": [{"cue": "If the candidate does not correct the weight-gain misconception, the SP must ask:", "line": "So will this make me gain weight like my coworker said?"}, {"cue": "If the candidate does not mention taking it with food, the SP must ask:", "line": "Should I take this on an empty stomach or with a meal?"}, {"cue": "If the candidate does not mention the contrast dye interaction, the SP must say:", "line": "Oh, I almost forgot — I'm getting a CT scan with dye in a few weeks. Does that matter?"}, {"cue": "If serious side effects have not been addressed, the SP must ask:", "line": "Is there anything dangerous I should watch out for with this?"}], "closingLine": "Okay, thank you, that helps."}, "assessor": {"solved": ["Corrects the misconception that metformin causes weight gain.", "Explains the mechanism in plain language and correct administration (with food, gradual titration).", "Addresses GI side effects and the rare but serious risk of lactic acidosis without causing undue alarm.", "Proactively identifies and explains the need to hold metformin around IV contrast dye or surgery.", "Provides a monitoring plan and clear red flags for seeking care."], "marginal": ["Corrects the weight-gain misconception but explains the mechanism only briefly.", "Explains administration instructions but omits the food/GI-upset rationale.", "Mentions side effects but does not proactively raise the contrast dye interaction unless prompted."], "uncertain": ["Corrects the weight-gain misconception OR explains side effects, but not both.", "Provides administration instructions only after being asked directly."], "unsolved": ["Fails to correct the incorrect belief that metformin causes weight gain.", "Fails to mention holding metformin around contrast dye studies even when directly prompted.", "Provides no guidance on managing or reporting side effects."]}, "printedMaterials": ["Drug Monograph", "Patient Record"]}, {"id": "o2", "ti": "New Prescription: Warfarin", "tl": 7, "type": "newrx", "sc": "Mrs. Eleanor Vasquez, 70, is starting warfarin 5 mg daily for newly diagnosed atrial fibrillation. She takes ibuprofen occasionally for arthritis and eats a diet rich in leafy greens.", "ta": "Counsel Mrs. Vasquez on her new warfarin therapy.", "cl": ["Introduction, identity confirmation, privacy check", "Asks about diet, other medications (flags OTC ibuprofen), alcohol use, allergies", "Explains action in plain language (prevents clot formation)", "Explains INR monitoring purpose, frequency, and target range", "Counsels on CONSISTENT (not avoided) vitamin K intake", "Advises against regular NSAID use; recommends acetaminophen and discussion with prescriber", "Reviews bleeding signs to watch for (bruising, blood in urine/stool, severe headache)", "Advises informing all prescribers/dentists about warfarin use before any new drug or procedure", "Closes, checks understanding, offers follow-up"], "mn": "Memory anchor: “CHAMPS” raise INR — Cipro, azoles, Metronidazole, Phenytoin, Sulfonamides.", "format": "patient", "objectives": ["To counsel a patient on a new prescription for an anticoagulant.", "To identify and address a potential drug and dietary interaction."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come to the counter to pick up a new prescription. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Eleanor Marie Vasquez", "gender": "Female", "age": 70, "behaviour": "Attentive and a little anxious about being on a 'blood thinner.'", "profile": ["Allergies: None known", "Medical History: Newly diagnosed atrial fibrillation", "Current Medications: Warfarin 5 mg PO daily (new); ibuprofen 200 mg PRN for arthritis pain", "Diet: Eats leafy green salads most days of the week"], "otherInfo": ["She takes ibuprofen two to three times a week for knee arthritis, sometimes up to 3 tablets a day.", "She was told to get 'blood tests' but doesn't know how often or what the target number is.", "She loves cooking with kale and spinach and is worried she'll have to give up her favourite salads.", "She occasionally has a glass of wine with dinner, a few times a week.", "She sees a dentist for a cleaning next month and hadn't thought to mention the new medication.", "She bruises a little more easily than she used to but assumed it was just aging."], "openingLine": "The doctor started me on this warfarin for my heart, but I heard it's a 'blood thinner' and I'm a little nervous. What do I need to know?", "responses": [{"cue": "If the candidate does not ask about NSAID use, the SP must say:", "line": "I do take ibuprofen for my knees sometimes — is that alright?"}, {"cue": "If the candidate does not address her diet, the SP must ask:", "line": "Do I need to stop eating my salads? I have greens almost every day."}, {"cue": "If INR monitoring is not explained, the SP must ask:", "line": "How will they know if this medicine is working right?"}, {"cue": "If bleeding precautions are not covered, the SP must say:", "line": "I have noticed I bruise more easily lately — should I be worried?"}], "closingLine": "Thank you, that's very helpful."}, "assessor": {"solved": ["Identifies ibuprofen use and advises against regular NSAID use, recommending acetaminophen instead.", "Explains that vitamin K intake should stay consistent rather than being avoided.", "Explains INR monitoring purpose, frequency, and target range in plain language.", "Reviews bleeding precautions and red-flag symptoms requiring urgent attention.", "Advises informing all other prescribers and her dentist about warfarin use."], "marginal": ["Identifies the NSAID interaction but the explanation is incomplete or delayed until prompted.", "Advises on vitamin K consistency but only after the patient raises her diet.", "Mentions INR monitoring without giving a clear target range or frequency."], "uncertain": ["Addresses either the NSAID interaction or the dietary/vitamin K issue, but not both.", "Provides bleeding precautions only when directly asked."], "unsolved": ["Tells the patient to avoid all vitamin-K-containing vegetables entirely.", "Does not identify or address the NSAID interaction even when prompted.", "Fails to provide any bleeding-related red flags."]}, "printedMaterials": ["Drug Monograph", "Patient Record"]}, {"id": "o3", "ti": "OTC Triage: Chronic Cough", "tl": 7, "type": "otc", "sc": "A 61-year-old man asks for a “strong cough syrup.” The cough is dry, not productive, and has lasted about 6 weeks. He takes ramipril for hypertension.", "ta": "Assess and counsel this patient using an appropriate framework.", "cl": ["Introduces self, clarifies who the medication is for", "WWWHAM-style assessment: onset/duration, character, associated symptoms, what's been tried, medications/history", "Identifies ramipril as the likely cause of the chronic dry cough", "Recognizes red flag: cough >3–4 weeks warrants medical assessment", "Avoids simply recommending a cough suppressant without addressing the cause", "Recommends follow-up with prescriber to discuss switching to an ARB", "Explains the rationale in plain language — common, not dangerous, but worth addressing", "Checks understanding and offers appropriate referral"], "mn": "Exam trap: ACE-inhibitor cough is a classic OSCE setup — always ask about medications.", "format": "patient", "objectives": ["To gather relevant information and assess a patient presenting with a non-prescription request.", "To identify a drug-induced cause of the patient's symptom and provide appropriate counsel and referral."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.3 Develop a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A person will come to the counter asking for a non-prescription product. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Walter Higgins", "gender": "Male", "age": 61, "behaviour": "A bit impatient; wants a quick fix and is initially reluctant to answer questions.", "profile": ["Allergies: None known", "Medical History: Hypertension, diagnosed 8 months ago", "Current Medications: Ramipril 10 mg PO daily", "Social History: Retired construction worker; former smoker (quit 10 years ago)"], "otherInfo": ["The cough started gradually about 6 weeks ago, around the same time his ramipril dose was increased.", "It's a dry, tickly cough with no phlegm, worse at night and when lying down.", "He has not had fever, chest pain, weight loss, or shortness of breath.", "He tried an over-the-counter cough drop and honey, without relief.", "He hasn't mentioned the cough to his doctor because he assumed it was 'just a cold that won't quit.'", "He is anxious to get back to his day and just wants something strong off the shelf."], "openingLine": "Can you just point me to your strongest cough syrup? I've had this cough for weeks and I just want it gone.", "responses": [{"cue": "If the candidate does not ask about duration, the SP must say:", "line": "It's been going on for about six weeks now, if that matters."}, {"cue": "If the candidate does not ask about current medications, the SP must say:", "line": "I don't take much, just a blood pressure pill."}, {"cue": "If the candidate recommends a cough product without further assessment, the SP must ask:", "line": "So this syrup will just clear it right up?"}, {"cue": "If referral is not clearly recommended, the SP must ask:", "line": "Do I really need to bother my doctor about a cough?"}], "closingLine": "Alright, I suppose I can call them."}, "assessor": {"solved": ["Conducts a structured symptom assessment (onset, character, associated symptoms, medications).", "Identifies ramipril as the likely cause of the chronic dry cough.", "Recognizes the red flag of a cough lasting longer than 3-4 weeks warranting medical assessment.", "Avoids recommending a cough suppressant as the primary solution.", "Recommends follow-up with the prescriber to discuss an alternative agent (e.g., an ARB)."], "marginal": ["Identifies the ramipril association but explains the rationale only briefly.", "Recommends seeing the prescriber but is vague about why or when.", "Recommends a symptomatic product alongside referral rather than referral alone."], "uncertain": ["Recognizes the cough is prolonged but does not connect it to the ramipril.", "Recommends referral only after being asked directly whether he needs to see a doctor."], "unsolved": ["Recommends a cough suppressant/expectorant as a stand-alone solution without addressing the cause.", "Does not recognize the need for medical referral despite the 6-week duration.", "Reassures the patient the cough is nothing to worry about."]}, "printedMaterials": ["Non-prescription Products (cough/cold section)"]}, {"id": "o4", "ti": "Adverse Drug Reaction: Statin Myopathy", "tl": 7, "type": "adr", "sc": "Mrs. Okafor, 66, calls the pharmacy reporting new muscle aches in both thighs and dark-coloured urine since starting atorvastatin 40 mg three weeks ago.", "ta": "Respond to this call appropriately.", "cl": ["Introduces self, confirms patient identity", "Gathers details: onset, severity, bilaterality, dark urine, fever/weakness", "Recognizes possible statin-induced myopathy/rhabdomyolysis (dark urine is a serious red flag)", "Advises stopping the statin immediately and seeking prompt (same-day) medical assessment", "Explains the need for urgent CK and renal function testing", "Does not minimize symptoms or suggest 'wait and see'", "Documents the call and communicates with the prescriber", "Reassures the patient and outlines next steps and alternative options once safe", "Provides safety-netting: when to go to the ER"], "mn": "Symptom pattern: muscle pain + dark urine = STOP statin + check CK now.", "format": "patient", "objectives": ["To assess a patient-reported adverse drug reaction by telephone.", "To recommend an appropriate and urgent course of action."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care.", "1.5 Monitor the patient and collaborate with the patient and their circle of care to revise the plan for the patient's care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy and receive a telephone call from a patient. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Ngozi Okafor", "gender": "Female", "age": 66, "behaviour": "Sounds worried and slightly downplays her symptoms at first.", "profile": ["Allergies: None known", "Medical History: Hyperlipidemia, osteoarthritis", "Current Medications: Atorvastatin 40 mg PO daily (started 3 weeks ago); acetaminophen PRN for joint pain"], "otherInfo": ["The muscle aches are in both thighs, started about 5 days ago, and have been getting worse.", "She noticed her urine has looked darker than usual for the past 2 days.", "She has not had a fever but feels generally more tired than usual.", "She assumed the aches were just from getting older or from gardening over the weekend.", "She has not called her doctor yet because she didn't want to 'make a fuss.'", "She lives alone and would need someone to drive her if she has to go to the hospital."], "openingLine": "Hi, it's Ngozi Okafor calling — I've had these achy legs for a few days and I just wanted to check if that's normal with my new cholesterol pill.", "responses": [{"cue": "If the candidate does not ask about urine colour, the SP must say:", "line": "Now that you mention it, my urine has looked kind of dark the last couple of days."}, {"cue": "If the candidate suggests waiting to see if it improves, the SP must ask:", "line": "So it's okay if I just wait a few more days and see how it goes?"}, {"cue": "If the candidate does not clearly advise stopping the statin, the SP must ask:", "line": "Should I keep taking my cholesterol pill tonight?"}, {"cue": "If urgency is not conveyed, the SP must ask:", "line": "Do I really need to go in today, or can it wait until my regular appointment?"}], "closingLine": "Okay, thank you for taking this seriously."}, "assessor": {"solved": ["Gathers key details: onset, severity, bilaterality, dark urine, fever/weakness.", "Recognizes possible statin-induced myopathy/rhabdomyolysis given the dark urine red flag.", "Clearly advises stopping the statin immediately.", "Advises prompt (same-day) medical assessment with urgent CK and renal function testing.", "Documents the call and communicates with the prescriber."], "marginal": ["Recognizes the myopathy concern but does not clearly instruct the patient to stop the statin.", "Recommends medical follow-up but does not convey same-day urgency.", "Gathers most relevant details but misses asking about dark urine directly."], "uncertain": ["Recognizes something may be wrong but does not identify rhabdomyolysis as a possibility.", "Advises follow-up only at her next regular appointment rather than urgently."], "unsolved": ["Reassures the patient the symptoms are a normal statin side effect that will pass.", "Advises continuing the statin without medical evaluation.", "Does not recommend urgent assessment despite the dark urine finding."]}, "printedMaterials": ["Patient Record"]}, {"id": "o5", "ti": "Non-Adherence: Antihypertensive", "tl": 7, "type": "adherence", "sc": "Mr. Singh, 58, admits he stopped taking his amlodipine two months ago because “I don't want to be on pills for the rest of my life,” and he feels fine.", "ta": "Have this conversation with Mr. Singh using a patient-centred approach.", "cl": ["Builds rapport with a non-judgmental tone", "Explores his reasons and beliefs without confrontation", "Acknowledges his feelings rather than lecturing", "Explains the asymptomatic nature of hypertension and long-term risks in plain language", "Uses motivational interviewing — explores what matters to him personally", "Explores practical barriers (cost, side effects, forgetfulness) alongside beliefs", "Offers to problem-solve together (alternative agent, dosing aid, follow-up BP check)", "Avoids ultimatums; respects autonomy while being clear about risk", "Closes with one concrete, actionable next step"], "mn": "Framework: explore → acknowledge → inform → collaborate → follow up.", "format": "patient", "objectives": ["To explore a patient's reasons for medication non-adherence using a patient-centred approach.", "To collaboratively develop a plan to support ongoing therapy."], "competencies": [{"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}, {"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.3 Develop a plan for the patient's care in collaboration with the patient and their circle of care.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}], "instructions": "You are working in a community pharmacy. A patient you know well comes to the counter. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Gurpreet Singh", "gender": "Male", "age": 58, "behaviour": "Defensive at first, softens if approached without judgment.", "profile": ["Allergies: None known", "Medical History: Hypertension, diagnosed 1 year ago", "Current Medications: Amlodipine 5 mg PO daily (prescribed, but stopped 2 months ago)", "Social History: Works long hours as a taxi driver; feels generally well"], "otherInfo": ["He stopped the amlodipine because he had mild ankle swelling and didn't like taking a pill every day.", "He has not had his blood pressure checked since he stopped the medication.", "His father had a stroke in his 60s, but Gurpreet hasn't connected that to his own blood pressure.", "He worries about the cost of medications now that he's paying out of pocket for part of his plan.", "He sometimes forgets doses even when he does take medications, due to his irregular driving schedule.", "He would be open to trying again if there were a simpler option or a different medication."], "openingLine": "Honestly, I stopped taking that amlodipine a couple months ago — my ankles were swelling and I felt fine without it anyway.", "responses": [{"cue": "If the candidate responds with judgment or lecturing, the SP must say:", "line": "I'm not trying to be difficult, I just don't want to be on pills forever."}, {"cue": "If the candidate does not explore the ankle swelling side effect, the SP must say:", "line": "It wasn't just that I felt fine — my ankles were puffing up too."}, {"cue": "If the candidate does not explain the risks of untreated hypertension, the SP must ask:", "line": "But if I feel fine, what's really the harm in skipping it?"}, {"cue": "If no concrete plan is offered, the SP must ask:", "line": "So what do you actually suggest I do now?"}], "closingLine": "Alright, that sounds fair. Thanks for listening."}, "assessor": {"solved": ["Explores the patient's reasons and beliefs without judgment.", "Identifies ankle swelling as a contributing side effect alongside the belief that treatment is unnecessary.", "Explains the asymptomatic risks of untreated hypertension in plain, non-alarming language.", "Collaboratively proposes a concrete next step (e.g., alternative agent, BP recheck, follow-up with prescriber).", "Respects the patient's autonomy while being clear about the risk of stopping treatment."], "marginal": ["Explores reasons for stopping but responds with some judgment or a lecturing tone.", "Explains the risks of untreated hypertension but does not offer a specific next step.", "Identifies one barrier (either the side effect or the belief) but not both."], "uncertain": ["Acknowledges the patient's feelings but does not explain the risk of stopping the medication.", "Offers a plan only after being directly asked what to do."], "unsolved": ["Pressures or scolds the patient into restarting the medication without addressing his concerns.", "Agrees that stopping is fine since he feels well.", "Does not offer any follow-up or referral back to the prescriber."]}, "printedMaterials": []}, {"id": "o6", "ti": "Prescriber Call: Renal Dosing (SBAR)", "tl": 7, "type": "prescribercall", "sc": "A new prescription arrives for metformin 1000 mg BID for Mrs. Ahmed, 74, whose chart shows an eGFR of 25 mL/min/1.73m² from last week's labs.", "ta": "Call the prescriber's office to discuss this prescription using a structured framework.", "cl": ["Introduces self and pharmacy clearly", "Situation: states reason for the call up front", "Background: patient age, relevant history, recent labs", "Assessment: metformin inappropriate at this eGFR — lactic acidosis risk", "Recommendation: hold metformin, consider alternative, or confirm awareness of recent labs", "States the concern clearly and concisely, not vaguely", "Is respectful and collaborative, not confrontational", "Proposes a concrete next step or alternative agent", "Confirms the plan and who will follow up with the patient, then documents the call"], "mn": "Framework: SBAR — Situation, Background, Assessment, Recommendation.", "format": "hp", "objectives": ["To identify and explain a drug-related problem given a patient's renal function.", "To recommend an appropriate solution to the prescriber."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy. A new prescription has been received for a patient with reduced renal function. You must speak with the prescriber's office about this prescription. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Health Professional", "name": "Dr. Aaron Fennimore", "gender": "Any", "age": "Any", "behaviour": "Busy but willing to listen; open to suggestions.", "profile": ["Role: Family physician, calling from the prescriber's office", "Patient: Mrs. Ahmed, 74 years old", "Relevant Labs: eGFR 25 mL/min/1.73m² (drawn last week)", "Reason for prescription: newly diagnosed type 2 diabetes"], "otherInfo": ["Mrs. Ahmed was diagnosed with type 2 diabetes at her visit today and this is her first diabetes medication.", "The eGFR of 25 was flagged in her chart from labs drawn last week for an unrelated concern.", "The physician had not cross-referenced the recent renal function results when writing the metformin prescription.", "Mrs. Ahmed also has longstanding hypertension, managed with an ACE inhibitor.", "The physician is willing to consider an alternative agent if one is recommended.", "A follow-up appointment is already booked for Mrs. Ahmed in 2 weeks."], "openingLine": "Hi, this is Dr. Fennimore's office returning your call about Mrs. Ahmed's new prescription — what's the concern?", "responses": [{"cue": "If the candidate recommends a change without stating the problem first, the HP must ask:", "line": "Okay — but what exactly is the issue with the prescription?"}, {"cue": "If the candidate identifies the problem but doesn't explain the reasoning, the HP must ask:", "line": "Can you tell me a bit more about why that dose is a concern for her?"}, {"cue": "If the candidate has not yet offered a recommendation partway through the call, the HP must ask:", "line": "So what would you suggest instead?"}, {"cue": "If the candidate says to hold the prescription without proposing an alternative or monitoring plan, the HP must ask:", "line": "Is there something else we could start her on, or do we just wait?"}], "closingLine": "Thanks, I'll update the chart and let her know."}, "assessor": {"solved": ["Identifies that the prescribed metformin dose is inappropriate given the patient's eGFR of 25 mL/min/1.73m².", "Explains the rationale: increased risk of lactic acidosis with metformin use in severe renal impairment.", "Recommends holding/not dispensing metformin at this renal function.", "Recommends an appropriate alternative agent or a dose adjustment consistent with renal dosing guidelines.", "Confirms the plan and documents the discussion."], "marginal": ["Identifies the renal concern but the explanation of risk is incomplete.", "Recommends holding the metformin but does not suggest a specific alternative.", "Reaches an acceptable recommendation only after several prompts from the physician."], "uncertain": ["Identifies a potential problem with the prescription but does not clearly connect it to renal function.", "Recommends closer monitoring only, without addressing the dosing problem directly."], "unsolved": ["Does not identify the renal contraindication/dosing problem.", "Agrees to fill the prescription as written without discussing the eGFR result.", "Recommends continuing the full dose with no adjustment or alternative."]}, "printedMaterials": ["Drug Monograph", "Patient Record", "Written Prescription"]}, {"id": "o7", "ti": "New Prescription: Inhaler Technique", "tl": 7, "type": "newrx", "sc": "Ms. Petrov, 24, is newly diagnosed with asthma and picking up her first salbutamol pMDI plus a low-dose ICS-formoterol inhaler.", "ta": "Counsel Ms. Petrov on both inhalers, including technique.", "cl": ["Introduction and identity confirmation", "Asks what she was told about her diagnosis and each medication's purpose", "Distinguishes reliever vs. maintenance/anti-inflammatory purpose clearly", "Demonstrates/explains pMDI technique: shake, exhale fully away from device, actuate at start of slow deep breath, hold ~10 seconds", "Mentions spacer use, especially for the ICS-containing inhaler", "Advises rinsing mouth after the ICS inhaler to prevent oral thrush", "Explains signs of poor control and when to seek urgent care", "Checks technique understanding by asking her to explain or demonstrate it back", "Closes with a follow-up plan (e.g., asthma action plan)"], "mn": "Technique cue: shake → exhale → actuate + slow inhale → hold 10 sec.", "format": "patient", "objectives": ["To counsel a patient on two new inhaled medications, including device technique.", "To ensure the patient can distinguish reliever from maintenance therapy."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come to the counter to pick up new prescriptions. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Anya Petrov", "gender": "Female", "age": 24, "behaviour": "A little overwhelmed; has never used an inhaler before.", "profile": ["Allergies: None known", "Medical History: Newly diagnosed asthma", "Current Medications: Salbutamol pMDI (new); ICS-formoterol low-dose inhaler (new)", "Social History: University student; works part-time as a barista"], "otherInfo": ["She was diagnosed after several weeks of nighttime coughing and shortness of breath during exercise.", "She has never used any inhaler before and is unsure which one is for 'emergencies.'", "She is worried about using the inhalers correctly and is embarrassed to ask her doctor to show her again.", "She plays recreational soccer twice a week and is worried about symptoms during games.", "She was not given a spacer device and doesn't know if she needs one.", "She has a follow-up appointment with her doctor in one month."], "openingLine": "I picked up these two inhalers but I honestly have no idea which one I'm supposed to use when, or how to even use them properly.", "responses": [{"cue": "If the candidate does not clearly distinguish reliever vs. maintenance use, the SP must ask:", "line": "So which one do I use if I suddenly feel short of breath?"}, {"cue": "If pMDI technique is not explained step-by-step, the SP must ask:", "line": "Can you show me exactly how I'm supposed to use this thing?"}, {"cue": "If mouth rinsing after the ICS inhaler is not mentioned, the SP must ask:", "line": "Is there anything special I need to do after using either of these?"}, {"cue": "If the candidate does not check her understanding, the SP must ask:", "line": "I think I've got it, but can you double check I'm doing it right?"}], "closingLine": "Great, thank you, that makes way more sense now."}, "assessor": {"solved": ["Clearly distinguishes the reliever (salbutamol) from the maintenance/anti-inflammatory inhaler.", "Explains and/or demonstrates correct pMDI technique (shake, exhale fully, actuate with slow deep breath, hold ~10 seconds).", "Mentions spacer use, particularly for the ICS-containing inhaler.", "Advises rinsing the mouth after the ICS inhaler to prevent oral thrush.", "Checks the patient's understanding by having her explain or demonstrate technique back."], "marginal": ["Distinguishes reliever from maintenance therapy but technique instructions are incomplete.", "Explains technique but does not mention spacer use or mouth rinsing.", "Provides correct information only after being asked directly to demonstrate."], "uncertain": ["Explains one inhaler's purpose and technique thoroughly but not the other.", "Does not check the patient's understanding of technique at all."], "unsolved": ["Does not distinguish which inhaler is for rescue use versus daily control.", "Gives incorrect or unsafe pMDI technique instructions.", "Provides no guidance on technique despite the patient stating she has never used an inhaler."]}, "printedMaterials": ["Drug Monograph", "Device Demonstration Inhaler (placebo)"]}, {"id": "o8", "ti": "Narcotic Refusal: Lost Prescription", "tl": 7, "type": "refusal", "sc": "A regular patient calls saying he lost his oxycodone prescription, filled 3 days ago, and asks for an early refill “just this once.”", "ta": "Handle this call appropriately, balancing empathy with regulatory requirements.", "cl": ["Introduces self and listens with an empathetic, non-accusatory tone", "Clearly explains narcotic prescriptions cannot be refilled/replaced without a new prescription (CDSA), regardless of the reason", "Explains the regulatory reasoning in plain, respectful language rather than a blunt refusal", "Sensitively assesses for safety concerns (withdrawal, pain crisis) without being accusatory", "Offers to contact the prescriber's office on the patient's behalf", "Avoids judgment even where diversion is a possible concern", "Documents the interaction thoroughly", "Discusses safe storage of controlled substances going forward if relevant", "Closes with clear next steps for the patient"], "mn": "For NARCS: no verbal orders, no transfers, no refills — everything needs paper.", "format": "patient", "objectives": ["To respond to a request for an early controlled-substance refill while balancing empathy with regulatory obligations.", "To apply relevant legislative requirements around narcotic prescriptions."], "competencies": [{"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements.", "5.2 Apply ethical principles to practice."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy and receive a telephone call from a regular patient. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Daniel Brooks", "gender": "Male", "age": 45, "behaviour": "Apologetic and a little embarrassed; becomes slightly frustrated if he feels accused.", "profile": ["Allergies: None known", "Medical History: Chronic low back pain following a workplace injury", "Current Medications: Oxycodone 5 mg tablets, filled 3 days ago; acetaminophen PRN"], "otherInfo": ["He says he lost the prescription bottle while moving apartments over the weekend.", "He denies taking extra doses and says he has about half the bottle left, aside from what was lost.", "He is not currently in a pain crisis but is worried about running out before his next appointment.", "He has never had this happen before and feels embarrassed about calling.", "He does not have a safe or lockbox at home for storing his medication.", "His next scheduled follow-up with his prescriber is in 3 weeks."], "openingLine": "Hey, it's Daniel Brooks — I know this sounds bad, but I lost my oxycodone prescription. Is there any way you could just refill it early, just this once?", "responses": [{"cue": "If the candidate flatly refuses without explaining the reason, the SP must ask:", "line": "Why not? I'm not trying to do anything wrong here."}, {"cue": "If the candidate does not offer to contact the prescriber, the SP must ask:", "line": "So what am I supposed to do now?"}, {"cue": "If the candidate sounds accusatory or judgmental, the SP must say:", "line": "I'm not trying to abuse anything, I really did just lose it."}, {"cue": "If safe storage is not discussed, the SP must ask:", "line": "Is there anything I should be doing differently so this doesn't happen again?"}], "closingLine": "Okay, I appreciate you helping me sort this out."}, "assessor": {"solved": ["Listens with an empathetic, non-accusatory tone throughout the call.", "Clearly explains that narcotic prescriptions cannot be refilled or replaced without a new prescription, regardless of the reason.", "Explains the regulatory rationale in respectful, plain language rather than a blunt refusal.", "Offers to contact the prescriber's office on the patient's behalf.", "Discusses safe storage of controlled substances going forward and documents the interaction."], "marginal": ["Explains the refill restriction but the explanation of rationale is brief or unclear.", "Offers to contact the prescriber but only after the patient asks what to do.", "Maintains a respectful tone but misses the safe-storage discussion."], "uncertain": ["Refuses the early refill but offers no alternative or next step.", "Explains the restriction in a way that sounds accusatory or dismissive."], "unsolved": ["Agrees to provide an early refill or override without a new prescription.", "Refuses the request in a judgmental or accusatory manner without explanation.", "Fails to document the call or interaction."]}, "printedMaterials": ["Patient Record"]}, {"id": "o9", "ti": "New Prescription: Levothyroxine", "tl": 7, "type": "newrx", "sc": "Mrs. Thompson, 45, is picking up her first prescription for levothyroxine 75 mcg daily for newly diagnosed hypothyroidism. She takes a daily calcium supplement.", "ta": "Counsel Mrs. Thompson on her new levothyroxine.", "cl": ["Introduction and identity confirmation", "Asks what she understands about her diagnosis and the medication", "Explains action in plain language (replaces a hormone her thyroid isn't making enough of)", "Critical instruction: empty stomach, 30–60 minutes before breakfast, same time daily", "Identifies the calcium supplement as interacting — separate by ≥4 hours", "Explains effects are gradual and dose may be adjusted based on follow-up labs", "Explains monitoring plan (TSH rechecked ~6–8 weeks after starting/dose change)", "Reviews signs of over-/under-replacement to report", "Checks understanding, invites questions, closes with follow-up"], "mn": "Separate levothyroxine from calcium/iron by ≥4 hours — chelation cuts absorption.", "format": "patient", "objectives": ["To counsel a patient on a new prescription for a chronic thyroid condition.", "To identify and manage a clinically significant absorption interaction."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come to the counter to pick up a new prescription. Assess the situation and respond as you would in practice.", "participant": {"role": "Simulated Participant", "name": "Karen Thompson", "gender": "Female", "age": 45, "behaviour": "Practical and eager to get clear, simple instructions.", "profile": ["Allergies: None known", "Medical History: Newly diagnosed hypothyroidism", "Current Medications: Levothyroxine 75 mcg PO daily (new); calcium carbonate 500 mg PO daily supplement", "Social History: Works an early morning shift; usually eats breakfast in the car"], "otherInfo": ["She usually takes her calcium supplement first thing in the morning with her coffee and breakfast.", "She was told she has an 'underactive thyroid' but doesn't fully understand what that means.", "She has been feeling tired and has noticed some weight gain over the past several months, which prompted testing.", "She has a follow-up blood test already booked, but isn't sure how soon it needs to happen.", "She sometimes forgets doses on busy mornings when she's rushing out the door.", "She takes no other regular prescription medications."], "openingLine": "I just picked up this levothyroxine — is there anything special I need to know about taking it, since I already take a calcium pill every morning?", "responses": [{"cue": "If the candidate does not give a specific timing instruction, the SP must ask:", "line": "So can I just take it whenever, like with my calcium pill?"}, {"cue": "If the calcium interaction is not addressed, the SP must ask:", "line": "Does it matter that I take a calcium supplement every morning too?"}, {"cue": "If the gradual onset of effect is not explained, the SP must ask:", "line": "How soon will I start feeling better once I start this?"}, {"cue": "If monitoring is not mentioned, the SP must ask:", "line": "Will I need more blood tests after this?"}], "closingLine": "Okay, that makes sense, thank you."}, "assessor": {"solved": ["Explains the critical dosing instruction: take on an empty stomach, 30-60 minutes before breakfast, at the same time daily.", "Identifies the calcium supplement as an interacting product and advises separating doses by at least 4 hours.", "Explains that the effect is gradual and dose may be adjusted based on follow-up labs.", "Explains the monitoring plan (TSH rechecked approximately 6-8 weeks after starting or a dose change).", "Reviews signs of over- and under-replacement to report."], "marginal": ["Gives the correct timing instruction but does not identify the calcium interaction unless asked.", "Identifies the calcium interaction but does not specify an adequate separation interval.", "Explains monitoring only in general terms without a specific timeframe."], "uncertain": ["Provides correct timing instructions but omits the calcium interaction entirely.", "Addresses the interaction only after the patient raises her calcium supplement."], "unsolved": ["Advises taking levothyroxine at the same time as, or without regard to, the calcium supplement.", "Provides no timing instructions relative to food.", "Does not mention any follow-up monitoring."]}, "printedMaterials": ["Drug Monograph", "Patient Record"]}, {"id": "o10", "ti": "New Prescription: Apixaban with Renal Check", "tl": 7, "type": "newrx", "sc": "Mr. Ibrahim, 78, is starting apixaban 5 mg BID for newly diagnosed atrial fibrillation. Recent labs: SCr 110 µmol/L, weight 58 kg.", "ta": "Counsel Mr. Ibrahim on his new anticoagulant, including confirming dose appropriateness.", "cl": ["Introduction and identity confirmation", "Reviews apixaban dose-reduction criteria (age ≥80, weight ≤60 kg, SCr ≥133 µmol/L — reduce if ≥2 of 3 met) and correctly applies them to this patient", "Explains action in plain language (prevents stroke-causing clots, no routine blood test needed unlike warfarin)", "Explains twice-daily dosing and what to do for a missed dose", "Reviews bleeding precautions and signs to report", "Advises informing all healthcare providers, including dentists, before procedures", "Cautions against combining with NSAIDs or other bleeding-risk agents without medical advice", "Notes renal function should still be reassessed periodically", "Checks understanding, closes with a follow-up plan"], "mn": "Apixaban reduced dose needs ≥2 of: age ≥80, weight ≤60 kg, SCr ≥133 µmol/L.", "format": "patient", "objectives": ["To counsel a patient on a new prescription for an oral anticoagulant, including confirming dose appropriateness.", "To apply renal, age, and weight-based dosing criteria during an interactive counselling encounter."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient who was recently prescribed a new oral anticoagulant will come in to pick up his prescription and ask questions. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Karim Haidari", "gender": "Male", "age": 78, "behaviour": "Anxious about starting a new blood thinner but willing to listen.", "profile": ["Allergies: None known", "Medical History: Atrial fibrillation diagnosed 2 weeks ago; mild chronic kidney disease; hypertension", "Current Medications: Apixaban 5 mg twice daily (new); amlodipine 5 mg once daily", "Recent Labs: Serum creatinine 110 micromol/L; weight 58 kg"], "otherInfo": ["He read online that blood thinners require regular blood tests and is confused why none were ordered for this one.", "He takes ibuprofen roughly twice a week, purchased over the counter, for knee arthritis pain.", "He has a dental cleaning appointment booked for next month.", "His weight has been stable at about 58 kg for the past year.", "He lives with his daughter, who helps him organize his weekly pillbox.", "He drinks one glass of wine on weekend evenings."], "openingLine": "The doctor started me on this new pill for my heart rhythm, but I heard you need blood tests for blood thinners — nobody's booked me for any. Can you explain this to me?", "responses": [{"cue": "If the candidate does not explain why apixaban requires no routine coagulation monitoring, the SP must ask:", "line": "So how will anyone know if this medicine is working, or if I'm at risk of bleeding, if there's no blood test?"}, {"cue": "If the candidate does not ask about other medications he takes, the SP must say:", "line": "Oh, I should mention — I take ibuprofen for my knee sometimes."}, {"cue": "If the candidate does not address what to do before dental or medical procedures, the SP must ask:", "line": "I have a dental cleaning next month — is that something I need to worry about?"}, {"cue": "By the 5-minute mark, if bleeding precautions have not been discussed, the SP must ask:", "line": "Is there anything I should watch for now that I'm on this?"}], "closingLine": "Thank you, that clears things up."}, "assessor": {"solved": ["Correctly applies dose-reduction criteria (only 1 of 3 met — weight ≤60 kg) and confirms 5 mg BID is the appropriate standard dose.", "Explains the rationale for no routine coagulation monitoring.", "Identifies and addresses the ibuprofen interaction as an added bleeding risk.", "Advises informing the dentist and all prescribers of anticoagulant use before the upcoming procedure.", "Reviews bleeding precautions and red-flag symptoms to report."], "marginal": ["Confirms the dose is appropriate but does not clearly explain the reasoning behind the criteria.", "Mentions bleeding precautions but without specific red-flag symptoms.", "Identifies the NSAID interaction but does not explain the mechanism or offer an alternative."], "uncertain": ["Confirms the dose is appropriate OR addresses the NSAID interaction, but not both.", "Provides only generic anticoagulant counselling without tailoring it to this patient's renal/weight profile."], "unsolved": ["Incorrectly recommends a dose reduction (2.5 mg BID) despite only one dose-reduction criterion being met.", "Fails to identify the concurrent NSAID use as a bleeding risk.", "States that routine INR monitoring is required, causing confusion or false reassurance."]}, "printedMaterials": ["Drug Monograph (Apixaban)", "Patient Record", "Calculator"]}, {"id": "n1", "ti": "New Prescription: Rivaroxaban", "tl": 7, "type": "newrx", "sc": "Mr. Antoine Fortin, 68, is picking up his first prescription for rivaroxaban 20 mg once daily for newly diagnosed nonvalvular atrial fibrillation. He mentions he usually skips breakfast and just has coffee in the morning.", "ta": "Counsel Mr. Fortin on his new anticoagulant.", "cl": ["Introduces self, confirms patient identity (name + DOB), and checks privacy/consent to counsel", "Asks what he was told about his diagnosis and why this medication was prescribed", "Screens for allergies, other medications (including NSAIDs/ASA), and renal function history", "Explains action in plain language (reduces the risk of a stroke-causing clot forming in the heart)", "Critical instruction: rivaroxaban 20 mg must be taken WITH FOOD — a full meal — since absorption drops substantially on an empty stomach", "Addresses his skipped-breakfast habit directly, advising he take it with his largest meal of the day at a consistent time", "Reviews bleeding precautions and signs to report (unusual bruising, blood in urine/stool, severe headache)", "Advises informing all prescribers and dentists about rivaroxaban before any new drug or procedure", "Checks understanding, invites questions, and closes with a follow-up plan (periodic renal function check)"], "mn": "Exam trap: rivaroxaban's absorption depends on food at the 15/20 mg doses — apixaban and dabigatran carry no such requirement.", "format": "patient", "objectives": ["To counsel a patient on a new prescription for an oral anticoagulant with a specific food requirement.", "To address a lifestyle habit that could compromise medication efficacy."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient picking up a new oral anticoagulant prescription will come in with questions about how to take it. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Denis Rochon", "gender": "Male", "age": 68, "behaviour": "Casual and a little rushed; open to practical suggestions.", "profile": ["Allergies: None known", "Medical History: Newly diagnosed nonvalvular atrial fibrillation; hyperlipidemia", "Current Medications: Rivaroxaban 20 mg once daily (new); atorvastatin 20 mg at bedtime"], "otherInfo": ["He typically skips breakfast and just has black coffee before work.", "He was told by his cardiologist to \"take one pill a day\" but doesn't remember hearing anything about food.", "He plays recreational hockey once a week and has had minor cuts and bruises from it before.", "He occasionally takes ibuprofen after hockey games for muscle soreness.", "He has a routine dental checkup booked in three weeks.", "He lives with his wife, who reminds him about his cholesterol pill each night."], "openingLine": "I just picked up this new pill for my heart rhythm — the doctor said take one a day, that's about all I remember. Can you go over it with me?", "responses": [{"cue": "If the candidate does not specifically ask about his morning routine or food intake, the SP must say:", "line": "I'm usually in a rush in the morning — just coffee, no time for breakfast."}, {"cue": "If the candidate does not clearly state the medication must be taken with a full meal, the SP must ask:", "line": "Does it matter if I take it on an empty stomach?"}, {"cue": "If the candidate does not ask about other medications, the SP must say:", "line": "I take ibuprofen sometimes after hockey, for sore muscles."}, {"cue": "By the 5-minute mark, if bleeding precautions have not been covered, the SP must ask:", "line": "Is there anything I should be careful about now, playing hockey and everything?"}], "closingLine": "Thanks, that's helpful."}, "assessor": {"solved": ["Clearly explains rivaroxaban 20 mg must be taken with a full meal, and ties this directly to his skipped-breakfast habit with a practical solution (e.g., take with dinner instead).", "Identifies concurrent ibuprofen use as an added bleeding risk and advises acetaminophen as a safer alternative.", "Reviews bleeding precautions relevant to his hockey activity and red flags to report.", "Advises informing all prescribers and dentists of anticoagulant use before procedures."], "marginal": ["Mentions the food requirement but does not concretely tie it to his specific breakfast-skipping habit.", "Identifies the NSAID interaction but does not suggest an alternative.", "Reviews bleeding precautions only in general terms."], "uncertain": ["Explains the food requirement OR addresses the NSAID interaction, but not both.", "Provides correct information but does not confirm the patient's understanding of how to adjust his routine."], "unsolved": ["States rivaroxaban may be taken without regard to food (incorrect for the 20 mg dose).", "Fails to identify the NSAID bleeding-risk interaction.", "Does not address his skipped-breakfast habit despite him raising it directly."]}, "printedMaterials": ["Drug Monograph (Rivaroxaban)", "Patient Record"]}, {"id": "n2", "ti": "New Prescription: Empagliflozin", "tl": 7, "type": "newrx", "sc": "Ms. Priya Nair, 59, is starting empagliflozin 10 mg once daily added to her metformin for type 2 diabetes with early kidney protection in mind. She mentions she's leaving for a two-week trip with long flights and is prone to yeast infections.", "ta": "Counsel Ms. Nair on her new SGLT2 inhibitor prescription.", "cl": ["Introduces self, confirms identity, and checks what she understands about why this was added to her regimen", "Screens allergies, current renal function (eGFR), and other medications, including diuretics", "Explains action in plain language (causes the kidneys to remove extra sugar through the urine)", "Warns of increased risk of genital yeast infections and reviews hygiene measures and prompt treatment if symptoms occur", "Explains the rare but serious risk of euglycemic diabetic ketoacidosis, which can occur even with normal blood glucose", "Reviews sick-day rules — hold the dose during illness, poor oral intake, dehydration, or before surgery", "Advises adequate hydration, especially relevant to her upcoming travel and long flights", "Reviews signs of dehydration/hypotension and DKA (nausea, vomiting, abdominal pain, unusual fatigue) to report immediately", "Checks understanding and closes with a follow-up/monitoring plan"], "mn": "SGLT2 inhibitors can trigger DKA with a NORMAL blood glucose — 'euglycemic DKA' is the classic exam trap, and sick-day rules are the counterpoint.", "format": "patient", "objectives": ["To counsel a patient on a new SGLT2 inhibitor added to existing diabetes therapy.", "To review sick-day management and travel-related precautions."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care.", "1.5 Monitor the patient and collaborate with the patient and their circle of care to revise the plan for the patient's care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient starting a new diabetes medication will come in to discuss her prescription before an upcoming trip. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Meera Chandran", "gender": "Female", "age": 59, "behaviour": "Practical and a little pressed for time; wants clear, actionable advice.", "profile": ["Allergies: None known", "Medical History: Type 2 diabetes (diagnosed 6 years ago); mild hypertension; overweight", "Current Medications: Metformin 1000 mg twice daily; empagliflozin 10 mg once daily (new); hydrochlorothiazide 12.5 mg once daily"], "otherInfo": ["She is leaving in four days for a two-week trip with two long connecting flights.", "She has had two genital yeast infections in the past year, both treated with an over-the-counter antifungal.", "She tends to limit fluids during flights because she doesn't like using the airplane washroom.", "She has never had a low blood sugar episode.", "She occasionally forgets her evening metformin dose when travelling.", "She currently has a mild head cold with a runny nose but no fever."], "openingLine": "My doctor added this new diabetes pill last week. I'm actually leaving in a few days for a long trip, so I wanted to make sure I know how to take it properly.", "responses": [{"cue": "If the candidate does not ask about genital or yeast infection history, the SP must say:", "line": "I should mention, I've had a couple of yeast infections this past year."}, {"cue": "If the candidate does not discuss hydration or travel precautions, the SP must ask:", "line": "Is there anything special I should do about drinking water on the flights?"}, {"cue": "If the candidate does not mention sick-day rules, the SP must say:", "line": "Actually, I've had a bit of a cold the last couple of days — does that change anything?"}, {"cue": "By the 5-minute mark, if serious warning signs have not been reviewed, the SP must ask:", "line": "Is there anything serious I should watch out for with this new pill?"}], "closingLine": "Okay, thank you, this is really helpful before my trip."}, "assessor": {"solved": ["Explains empagliflozin's mechanism and reviews genital yeast infection risk with hygiene and prompt-treatment advice, tailored to her history.", "Explains euglycemic DKA risk and reviews sick-day rules (hold dose during illness, poor intake, or dehydration), directly addressing her current cold.", "Advises adequate hydration specifically in the context of her upcoming flights.", "Reviews DKA and dehydration red flags requiring urgent care."], "marginal": ["Mentions yeast infection risk but does not link it to her prior history or hygiene measures.", "Mentions sick-day rules in general terms without applying them to her current cold.", "Advises hydration without connecting it to the travel context."], "uncertain": ["Explains yeast infection risk OR sick-day/DKA rules, but not both.", "Provides accurate general SGLT2 counselling without addressing her specific travel or illness context."], "unsolved": ["Fails to mention euglycemic DKA risk entirely.", "Advises continuing the medication as usual despite her current illness, without discussing sick-day hold criteria.", "Provides no guidance on hydration despite the travel context she raised."]}, "printedMaterials": ["Drug Monograph (Empagliflozin)", "Patient Record"]}, {"id": "n3", "ti": "New Prescription: Levetiracetam", "tl": 7, "type": "newrx", "sc": "Jordan Wu, 22, is picking up a new prescription for levetiracetam 500 mg PO BID after a first unprovoked seizure. He works as a delivery driver and is worried about missing work.", "ta": "Counsel Jordan on his new antiepileptic medication.", "cl": ["Introduces self, confirms identity, and asks what the neurologist told him about the diagnosis and plan", "Screens for allergies, other medications, and alcohol use", "Explains action in plain language (calms overactive electrical activity in the brain to help prevent further seizures)", "Emphasizes strict adherence — missed doses can trigger breakthrough seizures", "Counsels on mood/behavioural side effects (irritability, low mood) as a known class effect, and to report rather than stop the drug on his own", "Discusses driving restrictions — a mandated seizure-free interval applies before he can legally resume driving, and to confirm the exact timeline with his prescriber", "Explains the drug must never be stopped abruptly, even if he feels well, due to the risk of rebound/withdrawal seizures", "Reviews common early side effects (drowsiness, dizziness) and when to call the pharmacy versus seek urgent care", "Checks understanding, invites questions, and closes with a follow-up plan"], "mn": "Antiepileptics are never stopped abruptly, even after a single seizure — always taper under medical supervision.", "format": "patient", "objectives": ["To counsel a patient on a new antiepileptic medication after a first seizure.", "To address concerns about driving restrictions and occupational impact."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}, {"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements."]}], "instructions": "You are working in a community pharmacy. A patient recently prescribed a new antiepileptic medication after a first seizure will come in to pick up his prescription and ask questions. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Tyler Brennan", "gender": "Male", "age": 22, "behaviour": "Worried and a little defensive about his job situation.", "profile": ["Allergies: None known", "Medical History: First unprovoked generalized seizure eight days ago; otherwise healthy", "Current Medications: Levetiracetam 500 mg twice daily (new); no other regular medications"], "otherInfo": ["He works full-time as a delivery driver and is worried about losing his job if he can't drive.", "He hasn't told his employer about the seizure yet.", "The seizure happened at home while he was sleep-deprived after several night shifts in a row.", "He drinks alcohol socially, about 2 to 3 drinks on weekends.", "He lives alone and is worried about having another seizure without anyone around.", "He has not yet booked a follow-up appointment with the neurologist.", "His parents want him to move back home temporarily, but he doesn't want to."], "openingLine": "I just want to know how long I actually have to stay off work — I drive for a living and I can't afford to lose my job over one seizure.", "responses": [{"cue": "If the candidate does not address the driving restriction directly and clearly, the SP must ask:", "line": "So, exactly how many months are we talking about before I can drive again?"}, {"cue": "If the candidate does not counsel on strict adherence, the SP must ask:", "line": "What happens if I just forget a dose here and there — is that a big deal?"}, {"cue": "If the candidate does not address mood or behavioural side effects, the SP must say:", "line": "My buddy said this stuff can make you moody — is that true?"}, {"cue": "By the 5-minute mark, if the abrupt-discontinuation risk has not been mentioned, the SP must ask:", "line": "If I start feeling totally fine, can I just stop taking it?"}], "closingLine": "Alright, thanks for explaining all that."}, "assessor": {"solved": ["Clearly explains the driving restriction, including that the exact seizure-free interval is set by provincial regulation and must be confirmed with his prescriber or licensing authority, without giving a false specific timeline.", "Emphasizes strict adherence and the risk of breakthrough seizures with missed doses.", "Counsels on mood or behavioural side effects as a known class effect and advises reporting rather than self-discontinuing.", "Explains the medication must never be stopped abruptly due to rebound or withdrawal seizure risk."], "marginal": ["Addresses the driving restriction but is vague or provides an unconfirmed specific timeframe.", "Mentions the importance of adherence but does not explain the consequence of missed doses.", "Mentions side effects generally without specifying mood or behavioural effects."], "uncertain": ["Addresses the driving restriction OR the abrupt-discontinuation warning, but not both.", "Provides general antiepileptic counselling without addressing his specific occupational concern."], "unsolved": ["Tells him he can resume driving immediately, or confidently states an incorrect specific date.", "Suggests it is acceptable to stop the medication once he feels well.", "Dismisses his mood-related question without addressing it as a genuine, reportable side effect."]}, "printedMaterials": ["Drug Monograph (Levetiracetam)", "Patient Record"]}, {"id": "n4", "ti": "OTC Triage: Spreading Leg Redness", "tl": 7, "type": "otc", "sc": "A young man asks for 'the strongest bug bite cream' for a red patch on his lower leg he first noticed two days ago after gardening. On questioning, the area is now warm, tender, and visibly larger than yesterday, and he mentions feeling feverish and tired since last night.", "ta": "Assess and counsel this patient using an appropriate self-care framework.", "cl": ["Introduces self and clarifies the presenting complaint", "WWHAM-style assessment: onset, character, rate of spread, associated systemic symptoms (fever, fatigue), relevant medical history and allergies", "Identifies red flags: spreading erythema, warmth, tenderness, and systemic fever — inconsistent with a simple insect bite", "Recognizes this presentation is concerning for cellulitis and is not appropriate for self-care", "Avoids simply recommending a topical antihistamine or hydrocortisone without addressing the underlying concern", "Explains the concern in plain, non-alarming language and the need for prompt (same-day) medical assessment", "Advises interim comfort measures (elevation, tracking the border with a marker and date) while arranging assessment", "Provides safety-netting: seek emergency care immediately if red streaking develops, fever worsens, or the area rapidly enlarges", "Checks understanding and confirms he has a way to be seen promptly today"], "mn": "Spreading warmth plus fever on a 'bug bite' is a cellulitis red flag — refer same-day, don't just hand over a cream.", "format": "patient", "objectives": ["To assess a presenting skin complaint using a structured self-care framework and identify features requiring referral.", "To communicate the need for prompt medical assessment without causing undue alarm."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.3 Develop a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties."]}], "instructions": "You are working in a community pharmacy. A patient will approach the counter asking for an over-the-counter recommendation for a skin complaint. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Connor Whitfield", "gender": "Male", "age": 28, "behaviour": "Casual and dismissive of the seriousness of his symptoms at first.", "profile": ["Allergies: None known", "Medical History: Generally healthy, no chronic conditions", "Current Medications: None regularly; took one dose of ibuprofen yesterday for leg discomfort"], "otherInfo": ["The redness started as a small patch about the size of a coin two days ago, after gardening without gloves.", "It has roughly doubled in size since yesterday.", "The area is warm to the touch and mildly painful when pressed.", "He has felt feverish and unusually tired since last night, and his temperature this morning was 38.2°C.", "He does not recall any visible insect bite or puncture wound, just spreading redness.", "He does not have a family doctor and usually goes to a walk-in clinic.", "He is hesitant to go to the emergency department because he thinks it's \"probably nothing.\""], "openingLine": "Hey, I need something really strong for this bug bite — it's on my leg and it's kind of getting worse.", "responses": [{"cue": "If the candidate does not ask how the area has changed over time, the SP must say:", "line": "Yeah, it was way smaller yesterday — it's basically doubled since then."}, {"cue": "If the candidate does not ask about systemic symptoms, the SP must say:", "line": "Actually, I've been feeling pretty wiped out and a bit feverish since last night."}, {"cue": "If the candidate recommends only a topical product without addressing referral, the SP must ask:", "line": "So a cream is really all I need for this?"}, {"cue": "By the 5-minute mark, if urgency has not been communicated, the SP must ask:", "line": "Is this something I really need to get checked out today, or can it wait?"}], "closingLine": "Okay, I'll go get it looked at."}, "assessor": {"solved": ["Identifies red-flag features (spreading erythema, warmth, tenderness, fever, fatigue) inconsistent with a simple insect bite.", "Clearly explains this is not appropriate for self-care and recommends same-day medical assessment.", "Communicates urgency and rationale in plain, non-alarming language.", "Provides safety-netting (emergency care if streaking, worsening fever, or rapid enlargement occurs)."], "marginal": ["Identifies most red flags but is less thorough in explaining the rationale for referral.", "Recommends referral but does not clearly convey same-day urgency."], "uncertain": ["Recommends referral but also offers a topical or self-care product as if it were sufficient on its own.", "Identifies the red flags but does not clearly recommend referral."], "unsolved": ["Recommends only a topical bug-bite cream or antihistamine without addressing the need for referral.", "Fails to identify the systemic symptoms (fever, fatigue) as significant.", "Reassures the patient it is \"probably nothing\" and can wait several days."]}, "printedMaterials": []}, {"id": "n5", "ti": "OTC Triage: Burning with Urination in Pregnancy", "tl": 7, "type": "otc", "sc": "A woman who appears to be pregnant asks for cranberry extract capsules and a urinary alkalinizing powder for burning with urination that started yesterday. When asked, she confirms she is 22 weeks pregnant.", "ta": "Assess and counsel this patient using an appropriate self-care framework.", "cl": ["Introduces self and assesses the symptoms: onset, frequency, urgency, flank pain, fever, visible blood in urine", "Confirms pregnancy status and gestational age directly", "Recognizes pregnancy as an automatic exclusion from self-treatment for urinary symptoms", "Screens specifically for red flags suggesting pyelonephritis (fever, flank pain, nausea/vomiting) requiring urgent rather than routine referral", "Explains the rationale in plain language — an untreated urinary infection in pregnancy carries risk to both her and the pregnancy", "Does not recommend cranberry extract or a urinary alkalinizer as sole treatment", "Refers promptly for urinalysis/culture and pregnancy-safe antibiotic therapy", "Communicates urgency clearly without unnecessarily alarming her", "Checks understanding and confirms she has access to prompt care today"], "mn": "Pregnancy is an automatic red flag for urinary symptoms — always refer for testing and treatment, never self-care alone.", "format": "patient", "objectives": ["To assess urinary symptoms in a pregnant patient using an appropriate self-care framework.", "To recognize pregnancy as an automatic referral criterion and communicate urgency appropriately."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.3 Develop a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties."]}], "instructions": "You are working in a community pharmacy. A patient will approach the counter asking for over-the-counter products for urinary symptoms. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Simone Belanger", "gender": "Female", "age": 29, "behaviour": "Pleasant and eager for a quick fix; open to guidance once concern is explained.", "profile": ["Allergies: None known", "Medical History: Currently 22 weeks pregnant; otherwise healthy pregnancy to date", "Current Medications: Prenatal vitamin, once daily"], "otherInfo": ["The burning with urination started yesterday afternoon, along with needing to urinate more often than usual.", "She has not noticed any blood in her urine.", "She has no fever, chills, or back/flank pain.", "She has not had a urinary infection during this pregnancy before.", "A friend gave her leftover cranberry capsules, and she planned to pair them with a urinary alkalinizing powder.", "She has an obstetrician but her next scheduled appointment isn't for another three weeks.", "She is otherwise feeling well and the pregnancy has been uncomplicated so far."], "openingLine": "Hi, I've had some burning when I pee since yesterday — I was hoping to just grab some cranberry pills and one of those urinary alkalizer powders.", "responses": [{"cue": "If the candidate does not directly ask about pregnancy status, the SP must say:", "line": "Oh, I should mention, I'm 22 weeks pregnant right now."}, {"cue": "If the candidate does not screen for flank pain or fever, the SP must say:", "line": "No fever or back pain that I've noticed, just the burning."}, {"cue": "If the candidate suggests the cranberry/alkalinizer combination is acceptable, the SP must ask:", "line": "So it's fine for me to just use these then?"}, {"cue": "By the 5-minute mark, if referral has not been clearly recommended, the SP must ask:", "line": "Should I actually be seeing someone about this instead?"}], "closingLine": "Okay, I'll call my doctor's office right away."}, "assessor": {"solved": ["Confirms pregnancy status and gestational age, and screens for pyelonephritis red flags (fever, flank pain, nausea/vomiting).", "Recognizes pregnancy as an automatic exclusion from self-treatment for urinary symptoms.", "Explains the rationale (risk to both mother and pregnancy if untreated) in appropriate, non-alarming language.", "Refers promptly for urinalysis/culture and pregnancy-safe antibiotic therapy, and does not recommend cranberry extract or an alkalinizer as sole treatment."], "marginal": ["Confirms pregnancy and recommends referral but explains the rationale less thoroughly.", "Screens for red flags incompletely (e.g., misses fever or flank pain)."], "uncertain": ["Confirms pregnancy but does not clearly recommend referral, or recommends referral without confirming pregnancy details.", "Recommends referral but also suggests the cranberry/alkalinizer products may be used in the meantime."], "unsolved": ["Approves the use of cranberry extract and/or a urinary alkalinizer as appropriate self-treatment for a pregnant patient.", "Fails to recognize pregnancy as requiring referral at all.", "Does not screen for or recognize signs suggestive of pyelonephritis."]}, "printedMaterials": []}, {"id": "n6", "ti": "Adverse Drug Reaction: Bloody Diarrhea on Clindamycin", "tl": 7, "type": "adr", "sc": "A patient calls the pharmacy reporting five days of profuse watery diarrhea with occasional streaks of blood, cramping, and a low-grade fever, six days into a course of clindamycin his dentist prescribed for a tooth infection.", "ta": "Respond to this call appropriately.", "cl": ["Introduces self and confirms patient identity", "Gathers details: onset relative to starting clindamycin, stool frequency and character, fever, abdominal pain", "Recognizes this presentation as concerning for Clostridioides difficile-associated diarrhea rather than routine antibiotic-associated GI upset", "Advises stopping the clindamycin now", "Advises against antimotility agents such as loperamide, which can worsen the condition", "Advises prompt (same-day) medical assessment with stool testing for C. difficile toxin", "Explains that confirmed cases require a different targeted antibiotic (e.g., oral vancomycin or fidaxomicin), not just supportive care alone", "Advises hand hygiene with soap and water rather than alcohol-based sanitizer alone, since alcohol does not kill C. difficile spores", "Documents the call, communicates the concern to the prescriber, and provides safety-netting for worsening symptoms or dehydration"], "mn": "Bloody diarrhea after antibiotics means suspect C. difficile — stop the drug, skip the loperamide, and wash with soap, not just gel.", "format": "patient", "objectives": ["To assess a telephone report of a suspected antibiotic-associated adverse reaction and provide appropriate urgent guidance.", "To communicate concern to the prescriber and document the interaction appropriately."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy and receive a telephone call from a patient reporting a possible adverse drug reaction. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Gerald Simmons", "gender": "Male", "age": 61, "behaviour": "Worried and slightly embarrassed to be calling; cooperative when asked direct questions.", "profile": ["Allergies: Penicillin (hives as a child)", "Medical History: Dental abscess treated with clindamycin 300 mg four times daily for 7 days (currently day 6)", "Current Medications: Clindamycin (new, day 6 of 7); no other regular medications"], "otherInfo": ["He has a penicillin allergy, which is why the dentist chose clindamycin instead.", "The diarrhea started around day 3 of the antibiotic and has progressively worsened.", "He has had about 8 to 10 loose, watery stools in the past 24 hours.", "He noticed streaks of blood starting yesterday.", "He took two doses of loperamide yesterday hoping it would settle his stomach, without much improvement.", "He has felt a low-grade fever (around 37.8°C) and general fatigue since yesterday.", "He lives alone and is worried about becoming dehydrated.", "He has one clindamycin dose left in the course."], "openingLine": "Hi, I'm on this antibiotic for a tooth infection and I've had really bad diarrhea for days now, and I noticed some blood in it yesterday — I'm not sure if I should keep taking the pills.", "responses": [{"cue": "If the candidate does not ask about fever or systemic symptoms, the SP must say:", "line": "I've also had a low fever and I'm feeling pretty wiped out."}, {"cue": "If the candidate does not ask what he has already tried, the SP must say:", "line": "I took some loperamide yesterday but it didn't really help."}, {"cue": "If the candidate does not clearly advise stopping the clindamycin, the SP must ask:", "line": "Should I just finish out the last pill, since there's only one left?"}, {"cue": "By the 5-minute mark, if urgency has not been communicated, the SP must ask:", "line": "Do I need to go somewhere today, or can this wait until my next dentist visit?"}], "closingLine": "Okay, thank you, I'll go get checked out right away."}, "assessor": {"solved": ["Recognizes the presentation (bloody diarrhea, fever, onset during antibiotic therapy) as concerning for Clostridioides difficile-associated diarrhea, not routine antibiotic-associated GI upset.", "Advises stopping the clindamycin immediately, even with one dose remaining, and advises against further antimotility agents.", "Advises prompt, same-day medical assessment with stool testing for C. difficile toxin.", "Advises hand hygiene with soap and water rather than alcohol-based sanitizer alone, and documents/communicates the concern to the prescriber."], "marginal": ["Recognizes the likely diagnosis but is less thorough in explaining next steps (e.g., does not specify stool testing).", "Advises stopping the antibiotic but does not address the loperamide already taken."], "uncertain": ["Advises stopping the antibiotic OR recommends prompt assessment, but not both clearly.", "Recognizes something is wrong but frames it as routine antibiotic-associated diarrhea rather than a C. difficile concern."], "unsolved": ["Advises finishing the remaining antibiotic course as prescribed.", "Recommends continuing or restarting loperamide for symptom control.", "Advises the patient can wait until a routine appointment rather than seeking prompt assessment."]}, "printedMaterials": ["Patient Record"]}, {"id": "n7", "ti": "Adverse Drug Reaction: Lip and Tongue Swelling on Lisinopril", "tl": 7, "type": "adr", "sc": "A patient's spouse calls in a panic, saying her husband, who started lisinopril for hypertension eleven days ago, suddenly has a swollen lip and tongue and is having trouble speaking clearly.", "ta": "Respond to this call appropriately.", "cl": ["Introduces self, stays calm, and gathers essential details quickly: onset, breathing difficulty, voice change, throat tightness", "Recognizes this as angioedema, a rare but life-threatening ACE-inhibitor reaction", "Immediately advises calling 911 or going to the emergency department now, without delaying for further questions given possible airway compromise", "Clearly states the lisinopril must be stopped and never taken again", "Explains this reaction can occur days to weeks into therapy, not only with the first dose", "Advises against future use of any ACE inhibitor, and flags the need for caution (lower but nonzero cross-reactivity) if an ARB is considered later", "Ensures the reaction is documented as an allergy/intolerance in the patient's profile once the emergency is addressed", "Follows up with the family afterward to discuss an alternative antihypertensive class with the prescriber", "Does not minimize the situation or suggest waiting to see if it improves on its own"], "mn": "ACE-inhibitor angioedema can strike weeks into therapy — swelling of the lips, tongue, or throat is a 911 emergency, not a call-tomorrow issue.", "format": "patient", "objectives": ["To recognize and respond urgently to a life-threatening drug reaction reported by phone.", "To provide clear direction to a distressed caller while ensuring patient safety."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy and receive an urgent telephone call from a patient's family member reporting a possible adverse drug reaction. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Rosalind Carver", "gender": "Female", "age": 65, "behaviour": "Frightened and speaking quickly; needs clear, calm direction.", "profile": ["Allergies (patient/husband): None known prior to this reaction", "Medical History (patient/husband): Hypertension; started lisinopril 10 mg once daily eleven days ago", "Current Medications (patient/husband): Lisinopril 10 mg once daily (started 11 days ago); amlodipine discontinued when lisinopril was started"], "otherInfo": ["Her husband's lips and tongue started swelling about twenty minutes ago and it seems to be getting worse.", "He is talking but his words sound slurred or muffled because of the swelling.", "He has not had any hives, rash, or itching elsewhere on his body.", "He has no known drug allergies before this.", "He has not had any trouble breathing yet, but she is scared it could happen.", "This is the first time anything like this has happened since starting the new blood pressure pill.", "They do not have any diphenhydramine or an epinephrine auto-injector at home.", "She is currently in the car with him, deciding where to go."], "openingLine": "My husband just started this new blood pressure pill about a week and a half ago, and his lips and tongue are swelling up right now and he sounds like he can barely talk — what do I do?", "responses": [{"cue": "If the candidate does not immediately direct her to call 911 or go to the emergency department, the SP must ask urgently:", "line": "Should I just wait and see if it goes down on its own?"}, {"cue": "If the candidate does not clearly state to stop the lisinopril, the SP must ask:", "line": "Does he need to keep taking his pills today?"}, {"cue": "If the candidate does not ask about breathing or airway symptoms, the SP must say:", "line": "He's not having trouble breathing yet, but I'm scared it's going to get worse."}, {"cue": "By the 5-minute mark, if the candidate has not reinforced the emergency instruction, the SP must ask:", "line": "Are you sure this can't just wait until his doctor's office opens tomorrow?"}], "closingLine": "Okay, we're going to the ER right now — thank you."}, "assessor": {"solved": ["Immediately and clearly directs the caller to call 911 or go to the emergency department now, without delaying for extensive history-taking.", "Recognizes this as ACE-inhibitor angioedema and clearly states the lisinopril must be stopped and never taken again.", "Explains this reaction can occur days to weeks into therapy, not only with the first dose.", "Remains calm, communicates clearly with a distressed caller, and does not suggest waiting to see if it resolves."], "marginal": ["Advises emergency care but takes longer than necessary to get there by gathering excessive non-essential history first.", "Advises stopping the lisinopril but is less clear that it must never be restarted."], "uncertain": ["Advises emergency care OR advises stopping the drug clearly, but not both promptly.", "Provides correct advice but delivers it in a way that increases the caller's panic rather than directing her calmly."], "unsolved": ["Suggests waiting to see if the swelling improves before seeking care.", "Does not advise stopping the lisinopril, or suggests she can wait until the next scheduled dose to decide.", "Fails to recognize the urgency and does not direct her to call 911 or go to the emergency department now."]}, "printedMaterials": ["Patient Record"]}, {"id": "n8", "ti": "Immunization: Influenza Vaccine and Egg Allergy", "tl": 7, "type": "immunization", "sc": "Mr. Yusuf, 74, is due for his annual influenza vaccine but hesitates, telling you he was informed years ago that he 'can't get the flu shot' because he once had hives after eating scrambled eggs.", "ta": "Screen and counsel Mr. Yusuf on his influenza immunization.", "cl": ["Confirms identity, indication, and date of his last influenza vaccine", "Takes a focused history of the egg reaction to characterize its severity (hives only, no anaphylaxis, airway involvement, or hospitalization)", "Correctly identifies that egg allergy, even if severe, is NOT a contraindication to current influenza vaccines and no special precautions beyond routine observation are needed", "Screens for true contraindications/precautions: anaphylaxis to a prior dose of influenza vaccine itself or a vaccine component, current moderate-to-severe acute illness", "Obtains informed consent, explaining common local/systemic reactions and rare serious reactions in balanced, non-alarming language", "Describes proper administration technique and site", "Reviews aftercare: the standard 15-minute observation period and how to manage soreness or low-grade fever", "Corrects the outdated belief respectfully, without making him feel foolish for having asked", "Documents the immunization per the provincial immunization program"], "mn": "Egg allergy, even anaphylactic, is no longer a contraindication to flu vaccination — a persistent myth worth actively un-learning.", "format": "patient", "objectives": ["To screen a patient for contraindications and precautions before influenza immunization.", "To correct a misconception about egg allergy and vaccination in a respectful, non-judgmental manner."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}, {"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements."]}], "instructions": "You are working in a community pharmacy that provides influenza immunizations. A patient will come in for his annual flu shot and raise a concern about a past allergic reaction. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Elias Petrov", "gender": "Male", "age": 74, "behaviour": "A little embarrassed and hesitant, but open once reassured.", "profile": ["Allergies: Eggs (hives after eating scrambled eggs, decades ago; no anaphylaxis or airway involvement)", "Medical History: Hypertension; osteoarthritis", "Current Medications: Amlodipine once daily; acetaminophen as needed for joint pain"], "otherInfo": ["The hives after eating scrambled eggs happened when he was in his 30s; he has avoided eggs and flu shots ever since.", "He has never had a reaction to any vaccine before; this would be his first flu shot in several years.", "He has no history of anaphylaxis, throat swelling, or breathing difficulty from the egg reaction.", "He is not currently feeling unwell and has no fever today.", "He has never had a severe allergic reaction to any medication.", "He is a bit embarrassed that he may have been avoiding the vaccine unnecessarily for years.", "His wife also gets her flu shot every year at the same pharmacy.", "He is not on any blood thinners."], "openingLine": "I want to get my flu shot today, but years ago someone told me I can't get it because I once had a reaction to eggs — is that still true?", "responses": [{"cue": "If the candidate does not ask about the nature or severity of the egg reaction, the SP must say:", "line": "It was just hives, a long time ago — nothing like trouble breathing or anything."}, {"cue": "If the candidate does not clearly state that egg allergy is not a contraindication, the SP must ask:", "line": "So you're saying it's actually safe for me, even with the egg thing?"}, {"cue": "If the candidate does not mention the post-vaccination observation period, the SP must ask:", "line": "Do I need to stick around after, or can I just head out?"}, {"cue": "By the 5-minute mark, if informed consent and common side effects have not been discussed, the SP must ask:", "line": "Is there anything I should expect to feel afterward?"}], "closingLine": "Great, thank you for clearing that up — let's go ahead."}, "assessor": {"solved": ["Takes a focused history of the egg reaction and correctly characterizes it as non-anaphylactic.", "Correctly identifies that egg allergy, even if severe, is not a contraindication to current influenza vaccines, and explains this clearly and respectfully.", "Screens for true contraindications and precautions (e.g., prior anaphylaxis to influenza vaccine itself, current moderate-to-severe illness).", "Obtains informed consent, reviews common side effects and the post-vaccination observation period, and documents the immunization."], "marginal": ["Correctly states the vaccine is safe but does not clearly explain the reasoning to the patient.", "Screens for the egg reaction history but misses other true contraindications or precautions.", "Counsels appropriately but omits the observation period."], "uncertain": ["Determines the vaccine is appropriate but does not clearly correct the patient's misconception.", "Screens history adequately but hesitates or is unclear about whether to proceed."], "unsolved": ["Declines to give the vaccine or refers the patient elsewhere due to the egg allergy alone.", "Recommends a special precaution (e.g., extended observation, split-dosing, allergist referral) that is not indicated for this reaction history.", "Fails to screen for true contraindications, proceeding without appropriate assessment."]}, "printedMaterials": ["Immunization Consent Form", "Patient Record"]}, {"id": "n9", "ti": "Immunization: Pediatric Catch-Up During Chemotherapy", "tl": 7, "type": "immunization", "format": "patient", "sc": "A mother brings in her 6-year-old daughter for catch-up immunizations, including a second MMR dose, ahead of starting school. She mentions her daughter was recently diagnosed with acute lymphoblastic leukemia and started chemotherapy last month.", "ta": "Screen and counsel the mother on the requested immunizations.", "cl": ["Confirms identity, immunization history, and which vaccines are due for catch-up", "Identifies active chemotherapy-induced immunosuppression as a contraindication to live vaccines, including MMR, at this time", "Explains the reasoning in plain language — a live vaccine could cause actual infection in a child whose immune system cannot mount a normal response right now", "Clarifies that inactivated vaccines (e.g., inactivated influenza) generally remain appropriate and should not be delayed", "Advises deferring the MMR dose until cleared by the oncology team, with a plan to complete the series once immune function recovers", "Recommends household contacts stay up to date on their own vaccinations to indirectly protect the child", "Refers back to the treating oncologist or an immunization specialist for a personalized catch-up schedule rather than guessing", "Documents the deferred vaccine and the specific reason clearly in her record", "Closes with empathy, acknowledging this is a stressful and overwhelming time for the family"], "mn": "Live vaccines (MMR, varicella, live intranasal flu) are held during immunosuppression — inactivated vaccines generally are not.", "objectives": ["To assess a caregiver's request for catch-up immunizations in a child who has a relevant contraindication.", "To explain the rationale for deferring a live vaccine and provide a safe alternative plan."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy that provides immunization services. A parent will bring in her child to ask about catch-up vaccinations. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Renata Okafor", "gender": "Female", "age": 34, "behaviour": "Anxious but cooperative; eager to protect her daughter and worried about missing the school deadline.", "profile": ["Allergies: Daughter - none known", "Medical History: Daughter diagnosed with acute lymphoblastic leukemia one month ago, currently in induction chemotherapy", "Current Medications: Daughter's chemotherapy protocol is managed by the oncology team", "Immunization History: Daughter received her first MMR dose at 12 months of age"], "otherInfo": ["Her daughter's most recent chemotherapy dose was 4 days ago.", "No one from the oncology team has spoken to her about vaccines recently.", "She is worried her daughter will be barred from starting school without proof of complete immunization.", "As far as she knows, everyone else in the household is up to date on their own vaccines.", "She has not yet contacted the oncologist specifically about the immunization schedule.", "Her daughter has had no fever or new symptoms recently.", "She is willing to wait on any vaccine if it means keeping her daughter safe."], "openingLine": "Hi, my daughter's starting school soon and needs some catch-up shots, including her second MMR — but I should mention, she was just diagnosed with leukemia and started chemo last month. Is that a problem?", "responses": [{"cue": "If the candidate does not explain why the MMR must be deferred, the SP must ask:", "line": "But she really needs this for school — can't we just give it and see how she does?"}, {"cue": "If the candidate does not mention that inactivated vaccines remain appropriate, the SP must ask:", "line": "So does that mean she can't get any of her other shots today either?"}, {"cue": "If the candidate does not suggest confirming with the oncology team, the SP must ask:", "line": "Who do I even talk to about scheduling this once she's finished treatment?"}, {"cue": "By the 5-minute mark, if the deferral has not been clearly explained, the SP must say:", "line": "I just want to make sure I'm not putting her at risk by pushing this today."}], "closingLine": "Thank you, this really helps."}, "assessor": {"solved": ["Identifies chemotherapy-induced immunosuppression as a contraindication to the live MMR vaccine at this time.", "Clearly explains the rationale (risk of vaccine-strain infection in an immunosuppressed child).", "Confirms inactivated vaccines remain appropriate and should proceed without delay.", "Advises deferral until clearance from oncology, with a plan to complete the series once immune function recovers."], "marginal": ["Identifies the contraindication but explains the rationale less thoroughly.", "Confirms inactivated vaccines are fine but does not proactively specify which ones.", "Recommends deferral without specifying who to follow up with."], "uncertain": ["Identifies the contraindication but does not address whether inactivated vaccines can proceed.", "Advises deferral without providing any rationale to the mother."], "unsolved": ["Agrees to administer the live MMR vaccine as requested.", "Suggests giving a reduced or 'test' dose of the live vaccine to be cautious.", "Fails to identify the contraindication at all."]}, "printedMaterials": ["Immunization Schedule Reference", "Patient/Immunization Record"]}, {"id": "n10", "ti": "Calculation Station: Pediatric Amoxicillin Suspension", "tl": 7, "type": "calculation", "format": "patient", "sc": "A prescription arrives for amoxicillin oral suspension for a 3-year-old boy weighing 18 kg with acute otitis media, dosed at 40 mg/kg/day divided into three doses daily. The pharmacy stocks amoxicillin suspension 250 mg/5 mL.", "ta": "Calculate the volume of suspension required per dose and explain your reasoning to the examiner.", "cl": ["Extracts the relevant numbers: weight 18 kg, dose 40 mg/kg/day, three divided doses daily, stock concentration 250 mg/5 mL", "Sets up the total daily dose calculation explicitly: 40 mg/kg/day x 18 kg = 720 mg/day", "Divides correctly by the number of daily doses: 720 mg / 3 = 240 mg per dose", "Converts the per-dose amount to volume using the stock concentration (250 mg/5 mL = 50 mg/mL): 240 mg / 50 mg/mL = 4.8 mL per dose", "States the correct final answer clearly: 4.8 mL per dose, given three times daily", "Sanity-checks the answer against a typical single-dose suspension volume for a child this size (plausible, not an implausible extreme)", "Explains the reasoning aloud in an organized, stepwise manner rather than presenting only a final number", "Confirms the total daily volume (14.4 mL/day) is reasonable relative to the bottle size to be dispensed", "Notes the importance of counselling on use of an oral dosing syringe rather than a household spoon"], "mn": "Always convert dose to mg per administration, then mg to volume using the STOCK concentration, in that order — skipping a step is where marks are lost.", "objectives": ["To perform an accurate pediatric weight-based dose calculation.", "To explain the calculated dose clearly to the child's caregiver."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.8 Verify the accuracy and quality of dispensed products and preparations."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A parent is waiting at the counter while you verify the dose for her child's new prescription. Perform the calculation, showing your work, and explain the result to her in practical terms. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Priya Anand", "gender": "Female", "age": 32, "behaviour": "Polite but visibly nervous about giving her son the wrong amount of medicine.", "profile": ["Child's Allergies: None known", "Child's Medical History: Acute otitis media, diagnosed today", "Child's Current Medications: None regular; new amoxicillin oral suspension prescribed today", "Caregiver: mother, no relevant health conditions of her own"], "otherInfo": ["Her son weighs 18 kg per his pediatrician visit two weeks ago.", "He has never taken amoxicillin before but has tolerated other antibiotics without problems.", "She thinks the bottle looks unusually full and is worried it is 'too much medicine.'", "She does not have an oral dosing syringe at home, only kitchen spoons.", "The prescription was written by their family doctor after today's ear infection diagnosis.", "Her son is fussy about medicine taste and she worries he won't finish a full dose.", "She plans to keep the suspension refrigerated once home.", "She wants to know how many days the bottle will last."], "openingLine": "The doctor gave us this prescription, but that bottle looks really full — are you sure that's not too much for him at once?", "responses": [{"cue": "If the candidate does not clearly state the per-dose volume, the SP must ask:", "line": "Okay, so how many milliliters do I actually give him each time?"}, {"cue": "If the candidate does not mention using an oral dosing syringe, the SP must ask:", "line": "Can I just use a regular kitchen spoon to measure it?"}, {"cue": "If the candidate does not explain the total daily volume or how long the bottle will last, the SP must ask:", "line": "Is this bottle going to last the whole treatment, or will I need to come back?"}, {"cue": "By the 5-minute mark, if the dose has not been clearly explained, the SP must say:", "line": "I just want to make sure I'm not going to accidentally give him too much."}], "closingLine": "Okay, that makes sense now — thank you."}, "assessor": {"solved": ["Correctly calculates the total daily dose (720 mg/day) and the per-dose amount (240 mg).", "Correctly converts to volume using the stock concentration (4.8 mL per dose, three times daily).", "Shows all intermediate steps and units clearly.", "Clearly explains the per-dose volume and administration technique (oral dosing syringe) to the caregiver."], "marginal": ["Arrives at the correct final volume but skips or glosses over an intermediate step.", "Explains the dose to the caregiver but does not mention using an oral dosing syringe."], "uncertain": ["Makes a minor calculation or rounding error that does not materially change the clinical outcome.", "States a volume without showing or explaining the supporting work when asked."], "unsolved": ["Calculates an incorrect per-dose volume that could result in a clinically significant underdose or overdose.", "Recommends measuring the dose with a household spoon without correcting this."]}, "printedMaterials": ["Calculator", "Amoxicillin Suspension Product Monograph", "Prescription"]}, {"id": "n11", "ti": "Calculation Station: Weight-Based Heparin Infusion", "tl": 7, "type": "calculation", "format": "patient", "sc": "An 80 kg patient is to be started on an intravenous heparin infusion at an ordered rate of 18 units/kg/hour, using a premixed bag containing 25,000 units of heparin in 250 mL of D5W.", "ta": "Calculate the infusion pump rate in mL/hour and explain your reasoning to the examiner.", "cl": ["Extracts the relevant numbers: weight 80 kg, ordered rate 18 units/kg/hr, bag concentration 25,000 units/250 mL", "Calculates the required hourly dose first: 18 units/kg/hr x 80 kg = 1,440 units/hour", "Determines the bag concentration explicitly: 25,000 units / 250 mL = 100 units/mL", "Converts the hourly dose to a pump rate: 1,440 units/hour / 100 units/mL = 14.4 mL/hour", "States the correct final answer clearly with units: 14.4 mL/hour", "Sanity-checks that the rate is physiologically reasonable for a weight-based heparin infusion, not an extreme outlier", "Shows all intermediate steps and units explicitly rather than jumping straight to a final number", "Notes that heparin infusions require regular aPTT or anti-Xa monitoring with dose adjustment per nomogram", "Explains the calculation logic aloud clearly and confidently to the examiner"], "mn": "For weight-based infusions, find units-per-hour needed FIRST, then convert to mL/hour using the bag's concentration — never the reverse order.", "objectives": ["To perform an accurate weight-based intravenous infusion rate calculation.", "To communicate the calculated infusion rate clearly and confidently to a nurse."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.8 Verify the accuracy and quality of dispensed products and preparations."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties."]}], "instructions": "You are working as a hospital pharmacist. A nurse will come to verify the infusion pump rate for a new heparin order before starting it on her patient. Perform the calculation, showing your work, and communicate the rate clearly. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Colleen Marsh", "gender": "Female", "age": 40, "behaviour": "Professional and slightly rushed; wants a clear, confident answer she can act on immediately.", "profile": ["Role: Registered nurse, medical/surgical unit", "Patient in question: 80 kg adult with a new order for IV heparin infusion", "Order: Heparin 25,000 units in 250 mL D5W, ordered at 18 units/kg/hour", "Relevant status: Baseline aPTT already drawn per unit protocol"], "otherInfo": ["The patient has never received heparin before.", "The infusion pump requires a rate programmed in mL/hour.", "The prescriber's order is written as units/kg/hour, not as a pre-calculated pump rate.", "She has not started the infusion yet and is waiting on pharmacy confirmation.", "This is her first time hanging heparin on this particular patient.", "She wants to know when the next aPTT should be drawn.", "The order was flagged in the pharmacy system for pharmacist verification before dispensing."], "openingLine": "Hi, I've got a new heparin drip order for my patient and I need you to confirm the pump rate before I hang it — can you walk me through it?", "responses": [{"cue": "If the candidate does not state the intermediate units/hour calculation, the SP must ask:", "line": "How many units per hour is that working out to?"}, {"cue": "If the candidate does not clearly state the final mL/hour rate, the SP must ask:", "line": "So what do I actually set the pump to?"}, {"cue": "If the candidate does not mention aPTT or anti-Xa monitoring, the SP must ask:", "line": "Is there anything else I need to watch for or recheck after I start this?"}, {"cue": "By the 5-minute mark, if the rate has not been clearly confirmed, the SP must say:", "line": "I really need a firm number before I can hang this."}], "closingLine": "Great, thanks — I'll set it now."}, "assessor": {"solved": ["Correctly calculates the required hourly dose (1,440 units/hour).", "Correctly determines the bag concentration (100 units/mL).", "Correctly converts to the final pump rate (14.4 mL/hour) and states it clearly.", "Mentions the need for ongoing aPTT or anti-Xa monitoring with dose adjustment per nomogram."], "marginal": ["Arrives at the correct rate but shows incomplete working or hesitates on the final number.", "Provides the correct rate but omits the monitoring point."], "uncertain": ["Makes a minor calculation error that is not identified or corrected when questioned.", "States a rate without clear supporting steps when asked to explain."], "unsolved": ["Provides an incorrect infusion rate that could cause significant under- or over-anticoagulation.", "Confuses units/kg/hour with another unit (e.g., mL/kg/hour), producing a materially wrong rate."]}, "printedMaterials": ["Calculator", "Heparin Nomogram Reference", "Medication Order"]}, {"id": "n12", "ti": "Patient Assessment: New Low Back Pain", "tl": 7, "type": "assessment", "format": "patient", "sc": "Mr. Delgado, 44, a warehouse worker, comes in asking for something stronger than ibuprofen for low back pain that started two days ago after lifting a heavy box. He denies any leg symptoms when asked in general terms.", "ta": "Take a focused history and determine an appropriate plan for Mr. Delgado.", "cl": ["Introduces self and explains the purpose of the questions", "Applies a structured history: onset (lifting injury), provocation/palliation, quality, region/radiation, severity, timing and duration", "Actively and specifically screens for red flags: leg weakness or numbness, saddle anesthesia, new bowel or bladder changes, fever, unexplained weight loss, prior cancer history, significant trauma, IV drug use", "Asks about current medications, including the ibuprofen already tried (dose, duration, effectiveness), and allergies", "Confirms no neurological red flags are present, supporting a working diagnosis of mechanical/musculoskeletal low back strain", "States a clear plan: appropriate analgesic options, staying active rather than strict bed rest, heat application, and an expected recovery timeline", "Explains specifically when to return or seek urgent care if red flag symptoms develop", "Explains the plan to the patient in plain, reassuring language", "Documents the assessment and follow-up plan"], "mn": "Cauda equina red flags — saddle numbness, bowel/bladder changes, bilateral leg weakness — must always be asked about directly, even if the patient doesn't volunteer them.", "objectives": ["To take a focused history from a patient presenting with acute low back pain.", "To screen for red flags and determine an appropriate management plan."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.3 Develop a plan for the patient's care in collaboration with the patient and their circle of care.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will approach you asking for something stronger for his back pain. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Rafael Delgado", "gender": "Male", "age": 44, "behaviour": "Slightly impatient; wants a quick fix and initially downplays his symptoms.", "profile": ["Allergies: None known", "Medical History: No significant past medical history; occasional mechanical low back strain in the past", "Current Medications: Ibuprofen 400 mg, taken several times over the last two days", "Occupation: Warehouse worker with frequent heavy lifting"], "otherInfo": ["Pain started immediately after lifting a heavy box at work two days ago.", "The pain is a dull ache, worse with bending or twisting, better lying flat.", "He rates the pain about 6/10 now, down from 8/10 on the first day.", "He has taken ibuprofen 400 mg three times a day for two days with only partial relief.", "He denies any numbness, tingling, or weakness in his legs, but only if asked directly and specifically.", "He has had no fever, unexplained weight loss, or prior history of cancer.", "He has had no problems with bladder or bowel control.", "He is anxious to get back to work and wants something 'stronger' than ibuprofen."], "openingLine": "My back's been killing me since I lifted a box at work two days ago — the ibuprofen isn't cutting it, can I get something stronger?", "responses": [{"cue": "If the candidate does not directly address his request for a stronger medication after taking the history, the SP must ask:", "line": "So can I get something stronger, like what they gave my buddy — a muscle relaxant or something?"}, {"cue": "If the candidate does not advise staying active rather than bed rest, the SP must ask:", "line": "Should I just stay in bed until this gets better?"}, {"cue": "If the candidate does not explain when to seek urgent care, the SP must ask:", "line": "How would I know if this is something more serious?"}, {"cue": "By the 5-minute mark, if red flags have not been screened, the SP must say:", "line": "I just want to make sure this isn't something serious before I go back to lifting boxes."}], "closingLine": "Alright, that's helpful, thanks."}, "assessor": {"solved": ["Takes a structured pain history (onset, provocation/palliation, quality, radiation, severity, timing).", "Actively screens for all major red flags: leg weakness/numbness, saddle anesthesia, bowel/bladder changes, fever, unexplained weight loss, prior cancer, significant trauma.", "Confirms no red flags are present and recommends an appropriate analgesic plan with staying active rather than bed rest.", "Clearly explains when to seek urgent care if red flag symptoms develop."], "marginal": ["Takes a history but screens for red flags less thoroughly, missing one or two.", "Recommends a reasonable plan but does not clearly explain return precautions."], "uncertain": ["Takes a history but does not systematically screen for red flags.", "Recommends a plan without first confirming the absence of red flags."], "unsolved": ["Recommends a strong opioid or other inappropriate therapy without any red flag screening.", "Recommends strict, prolonged bed rest.", "Fails to screen for or address cauda equina red flags at all."]}, "printedMaterials": ["Non-prescription Analgesic Reference", "Patient Record"]}, {"id": "n13", "ti": "Difficult Conversation: New Palliative Pain Prescription", "tl": 7, "type": "difficult", "format": "patient", "sc": "Mrs. Alaoui, 61, was recently diagnosed with metastatic pancreatic cancer and comes in tearful with a new prescription for a long-acting opioid for pain control, saying, 'I don't understand why we're jumping straight to this — does this mean it's really over?'", "ta": "Have this conversation with Mrs. Alaoui.", "cl": ["Invites her to sit and finishes listening to what she's feeling before responding with information", "Does not interrupt or rush to correct her assumption", "Validates her emotion explicitly, acknowledging this is frightening and overwhelming news, before providing any facts", "Gently clarifies, once she seems ready to hear it, that starting a stronger pain medication is about controlling symptoms and quality of life, not necessarily an immediate end-of-life signal", "Provides balanced, accurate information about the medication itself (purpose, how it works, common side effects such as constipation and initial drowsiness, and that doses are titrated to comfort)", "Avoids overstepping scope of practice by making prognostic statements that belong to her oncology team", "Offers appropriate support resources (palliative care team, counselling or social work, patient support organizations)", "Checks in on how she's feeling and whether she has support at home", "Closes with a concrete next step (follow-up call, contact information) and leaves the door open for further questions"], "mn": "Validate the emotion first — a frightened patient cannot absorb medication counselling until she feels heard.", "objectives": ["To respond empathetically to a patient's emotional reaction to a new palliative prescription.", "To provide accurate medication information once the patient is ready to receive it."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}, {"code": "5", "label": "Professionalism", "elements": ["5.2 Apply ethical principles to practice."]}], "instructions": "You are working in a community pharmacy. A patient with a new prescription for pain control approaches the counter visibly upset. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Samira Alaoui", "gender": "Female", "age": 61, "behaviour": "Tearful and anxious; needs emotional space before she can absorb information.", "profile": ["Allergies: None known", "Medical History: Metastatic pancreatic cancer, diagnosed recently", "Current Medications: New prescription for a long-acting opioid for pain control", "Support: Lives with her husband; has two adult children nearby"], "otherInfo": ["She was diagnosed about two weeks ago after months of vague abdominal symptoms.", "Her oncologist prescribed the new pain medication at today's appointment.", "She has not yet discussed prognosis in detail with her oncology team.", "She is afraid that starting a stronger pain medication means her doctors have given up on her.", "She has never taken an opioid before and is worried about becoming 'dependent' or overly drowsy.", "Her husband is supportive but has been avoiding talking about the diagnosis with her.", "She has not yet been referred to a palliative or supportive care team.", "She has a follow-up oncology appointment in two weeks."], "openingLine": "(tearfully) I don't understand why we're jumping straight to this — does this mean it's really over?", "responses": [{"cue": "If the candidate responds with clinical facts before acknowledging her emotion, the SP must become more distressed and repeat:", "line": "You don't understand — why would they give me this now?"}, {"cue": "If the candidate does not clarify that starting the medication is about comfort and quality of life rather than an end-of-life signal, the SP must ask:", "line": "So is my doctor saying there's nothing more they can do for me?"}, {"cue": "If the candidate does not mention available support resources, the SP must ask:", "line": "Is there anyone else I can talk to about all of this, besides you?"}, {"cue": "By the 5-minute mark, if her emotional concern has not been directly addressed, the SP must say (still tearful):", "line": "I just need someone to tell me honestly what's going on."}], "closingLine": "Thank you... I think I needed to hear that."}, "assessor": {"solved": ["Allows her to express her emotion fully before responding with information.", "Explicitly validates her fear and distress before providing facts.", "Clarifies, once she is ready, that the medication addresses pain and quality of life and is not by itself an end-of-life signal.", "Provides accurate, balanced medication information without making prognostic statements outside scope of practice.", "Offers appropriate support resources (palliative care, counselling, patient support organizations)."], "marginal": ["Validates her emotion but moves to information less sensitively or too quickly.", "Provides medication information but omits support resources."], "uncertain": ["Provides accurate medication information but does not meaningfully address her emotional concern.", "Offers support resources but does not clarify the purpose of the medication."], "unsolved": ["Makes definitive prognostic statements (e.g., estimating time remaining) beyond scope of practice.", "Dismisses or minimizes her emotional reaction.", "Provides no emotional acknowledgment at all before launching into counselling."]}, "printedMaterials": ["Opioid Patient Information Leaflet", "Palliative/Supportive Care Resource List"]}, {"id": "m1", "ti": "New Prescription: Methotrexate for RA", "tl": 7, "type": "newrx", "format": "patient", "sc": "Mrs. Patricia Nguyen, 52, is starting methotrexate 15 mg PO once weekly for newly diagnosed moderate rheumatoid arthritis, along with folic acid supplementation. She mentions she occasionally takes trimethoprim-sulfamethoxazole for recurrent urinary tract infections.", "ta": "Counsel Mrs. Nguyen on her new methotrexate therapy.", "cl": ["Introduces self, confirms patient identity, and checks privacy to counsel", "Asks what she understands about her diagnosis and why methotrexate was chosen", "States clearly that the dose is taken ONCE WEEKLY on a fixed day, never daily", "Explains folic acid is taken on a different day to reduce GI upset and blood count side effects", "Identifies trimethoprim-sulfamethoxazole as a significant interaction (increased bone marrow suppression risk) and advises contacting the prescriber before continuing it", "Explains onset is slow (weeks to months) and short-term NSAID use may still be needed for symptom control", "Reviews red flags to report immediately: unusual bruising/bleeding, mouth sores, persistent cough or shortness of breath, yellowing of skin", "Confirms reliable contraception given teratogenicity and advises against alcohol use", "Explains the monitoring plan (baseline and periodic CBC, liver enzymes, renal function) and closes with follow-up"], "mn": "\"Once weekly, not daily\" is the single highest-stakes counselling point for methotrexate — accidental daily dosing has caused fatalities.", "objectives": ["To counsel a patient on a new prescription for once-weekly methotrexate.", "To identify and address a clinically significant drug interaction."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come in to discuss a new prescription. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Patricia Nguyen", "gender": "Female", "age": 52, "behaviour": "Attentive and cooperative, but not fully aware of the risks of her new medication.", "profile": ["Allergies: None known", "Medical History: Newly diagnosed moderate rheumatoid arthritis; recurrent urinary tract infections", "Current Medications: Trimethoprim-sulfamethoxazole (as needed for UTIs), occasional acetaminophen", "New Prescription: Methotrexate 15 mg PO once weekly with folic acid supplementation"], "otherInfo": ["She was diagnosed with rheumatoid arthritis about two weeks ago by her rheumatologist.", "She has taken trimethoprim-sulfamethoxazole on and off over the past year for recurrent UTIs, most recently about three weeks ago.", "She does not currently have an active UTI or a course of the antibiotic on hand.", "She assumed the methotrexate would be taken every morning like her other pills.", "She was not told by her rheumatologist to avoid alcohol.", "She is not currently planning a pregnancy but has not discussed contraception with her doctor.", "She gets mild nausea when taking medications on an empty stomach.", "She has not had any bloodwork done since starting methotrexate."], "openingLine": "I picked up this new arthritis medication, methotrexate — should I just take it every morning like my other pills?", "responses": [{"cue": "If the candidate does not clearly correct the daily-dosing assumption, the SP must ask:", "line": "Wait, so I'm NOT supposed to take it every day?"}, {"cue": "If the candidate does not ask specifically about her other medications, the SP must add, once asked generally:", "line": "Oh, I do take an antibiotic sometimes for bladder infections — does that matter?"}, {"cue": "If the candidate does not review red flags to report, the SP must ask:", "line": "Is there anything I should watch out for once I start taking this?"}, {"cue": "By the 5-minute mark, if once-weekly dosing has not been unambiguously confirmed, the SP must say:", "line": "I just want to be totally sure I'm not going to take this the wrong way."}], "closingLine": "Okay, thank you — that's really important to know."}, "assessor": {"solved": ["Clearly and unambiguously states methotrexate is taken once weekly on a fixed day, never daily.", "Identifies trimethoprim-sulfamethoxazole as a significant interaction and advises contacting the prescriber before continuing it.", "Explains folic acid timing and reviews red flags to report immediately.", "Confirms the monitoring plan and contraception/alcohol precautions."], "marginal": ["States once-weekly dosing but explains the fixed-day instruction or rationale less thoroughly.", "Identifies the antibiotic interaction but does not clearly advise a next step."], "uncertain": ["States once-weekly dosing but does not identify the drug interaction.", "Identifies the interaction but is unclear or inconsistent about weekly versus daily dosing."], "unsolved": ["Confirms or fails to correct daily dosing of methotrexate.", "Does not identify the trimethoprim-sulfamethoxazole interaction at all."]}, "printedMaterials": ["Drug Monograph: Methotrexate", "Patient Record"]}, {"id": "m2", "ti": "New Prescription: Alendronate for Osteoporosis", "tl": 7, "type": "newrx", "format": "patient", "sc": "Mrs. Loretta Fields, 68, is picking up her first prescription for alendronate 70 mg PO once weekly after a bone density scan showed a T-score of -2.6 at the hip. She also takes a combined calcium and vitamin D supplement each morning.", "ta": "Counsel Mrs. Fields on her new alendronate prescription, including proper administration.", "cl": ["Introduces self, confirms identity, and asks what she was told about her diagnosis", "Explains the action in plain language (slows bone breakdown to reduce fracture risk)", "States the critical administration rule: take first thing in the morning, on an empty stomach, with a full glass of plain water only", "Instructs her to remain upright (sitting or standing) for at least 30 minutes and not eat, drink, or take other medications during that time", "Identifies the calcium/vitamin D supplement as needing to be separated from the dose by at least 30-60 minutes to avoid impaired absorption", "Reviews red flags to report: new or worsening heartburn/chest pain, jaw pain, or unusual thigh/groin pain, and advises informing her dentist before invasive dental work", "Discusses that initial therapy typically runs 3-6 years before reassessing a possible drug holiday", "Checks her understanding and closes with a follow-up plan (repeat bone density testing in about 3 years)"], "mn": "Empty stomach, full glass of plain water, and staying upright for 30 minutes are three separate rules — missing any one risks esophageal irritation or ulceration.", "objectives": ["To counsel a patient on a new prescription for alendronate, including correct administration technique.", "To identify and resolve a timing interaction with an existing supplement."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come in to pick up a new prescription. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Loretta Fields", "gender": "Female", "age": 68, "behaviour": "Pleasant and eager to do things correctly, but has not yet been given clear administration instructions.", "profile": ["Allergies: None known", "Medical History: Osteoporosis, recently diagnosed via bone density scan (T-score -2.6 at the hip)", "Current Medications: Calcium/vitamin D combination supplement, taken each morning", "New Prescription: Alendronate 70 mg PO once weekly"], "otherInfo": ["Her doctor mentioned the new medication is 'for her bones' but did not explain how to take it.", "She usually takes her calcium/vitamin D supplement first thing in the morning with breakfast.", "She has mild, occasional heartburn but nothing frequent or severe.", "She has a dental cleaning scheduled in about two months.", "She sometimes lies back down after breakfast to read the newspaper.", "She was not told which day of the week to take the new medication.", "She has had no prior fractures.", "She is active and walks daily, weather permitting."], "openingLine": "The doctor said this new pill is for my bones, but she didn't really explain how to take it — can you help me with that?", "responses": [{"cue": "If the candidate does not explicitly state to take it on an empty stomach with plain water only, the SP must ask:", "line": "Can I take it with my morning coffee, or with my calcium pill?"}, {"cue": "If the candidate does not mention staying upright for at least 30 minutes, the SP must ask:", "line": "Is it okay if I lie down and read after I take it, like I usually do?"}, {"cue": "If the candidate does not separate the calcium/vitamin D supplement from the dose, the SP must ask:", "line": "So can I still take my calcium pill right after, at breakfast?"}, {"cue": "By the 5-minute mark, if the empty-stomach and upright instructions have not been clearly given, the SP must say:", "line": "I just want to make sure I'm taking this the right way so it actually works."}], "closingLine": "That's very helpful, thank you."}, "assessor": {"solved": ["States the critical rule: take first thing in the morning, on an empty stomach, with a full glass of plain water only.", "Instructs remaining upright for at least 30 minutes and avoiding food, drink, or other medications during that time.", "Identifies the calcium/vitamin D timing conflict and advises separating the doses by at least 30-60 minutes.", "Reviews red flags (new/worsening heartburn or chest pain, jaw pain, thigh/groin pain) and the dental precaution."], "marginal": ["Explains the empty-stomach/water rule but omits the upright-time instruction, or vice versa.", "Identifies the calcium interaction but does not give a specific separation interval."], "uncertain": ["Explains general administration but omits either the upright-time rule or the calcium separation.", "Mentions red flags but does not explain administration technique in any detail."], "unsolved": ["States it is fine to take the dose with food, other beverages, or immediately before lying down.", "Does not address the calcium/vitamin D timing conflict at all."]}, "printedMaterials": ["Drug Monograph: Alendronate", "Patient Record"]}, {"id": "m3", "ti": "Non-Adherence: Antipsychotic", "tl": 7, "type": "adherence", "format": "patient", "sc": "Mr. Adrian Kowalski, 27, has been stable on olanzapine 10 mg daily for schizophrenia for the past year. He quietly admits he has cut his dose in half over the last month because he has gained 8 kg and is embarrassed about it.", "ta": "Have this conversation with Mr. Kowalski using a patient-centred approach.", "cl": ["Builds rapport and opens with a non-judgmental question about how the medication has been going", "Explores his feelings about the weight gain without lecturing or dismissing his concern", "Acknowledges the impact of weight gain as valid before providing any clinical information", "Explains the risk of a reduced dose: possible relapse of psychotic symptoms and loss of hard-won stability", "Screens for early relapse warning signs (sleep changes, increasing suspiciousness, disorganized thinking)", "Discusses realistic options collaboratively (lifestyle support, or discussing a switch to an agent with lower weight-gain liability with his prescriber) rather than him unilaterally adjusting the dose", "Avoids ultimatums and respects his autonomy while being clear about relapse risk", "Closes with one concrete next step, such as arranging a prescriber follow-up before any further dose changes"], "mn": "Weight gain is one of the leading drivers of covert antipsychotic non-adherence — ask about it directly rather than waiting for it to surface as relapse.", "objectives": ["To explore a patient's reasons for covert medication non-adherence in a non-judgmental way.", "To collaboratively address the risk of relapse while respecting patient autonomy."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care.", "1.5 Monitor the patient and collaborate with the patient and their circle of care to revise the plan for the patient's care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient you know well comes in to pick up his refill. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Adrian Kowalski", "gender": "Male", "age": 27, "behaviour": "Initially guarded and embarrassed; opens up if approached without judgment.", "profile": ["Allergies: None known", "Medical History: Schizophrenia, diagnosed and clinically stable for the past year", "Current Medications: Olanzapine 10 mg daily (prescribed dose)", "Social: Lives independently, works part-time"], "otherInfo": ["He has actually been taking only 5 mg daily for about the last month, cutting his tablets in half.", "He has gained about 8 kg since starting olanzapine a year ago.", "He feels embarrassed and has not told his psychiatrist about the dose change.", "He has noticed some difficulty concentrating recently but attributes it to poor sleep.", "He has not had any hallucinations or unusual thoughts return so far, as far as he can tell.", "He is worried that mentioning the weight gain will make people think he wants to stop treatment entirely.", "He has a follow-up appointment with his psychiatrist in about six weeks.", "He has tried walking more and cutting back on soda, but the weight gain has continued."], "openingLine": "I'm just here to pick up my refill... actually, can I ask you something? I haven't been taking the full dose lately.", "responses": [{"cue": "If the candidate responds judgmentally or does not acknowledge his weight concern first, the SP must become more guarded and say:", "line": "I don't really want a lecture, I just wanted to mention it."}, {"cue": "If the candidate does not explain the relapse risk of the reduced dose, the SP must ask:", "line": "Is cutting it in half really going to make that big of a difference?"}, {"cue": "If the candidate does not screen for early relapse symptoms, the SP must add, only once asked generally how he's doing:", "line": "I've been having some trouble concentrating, but I figured that's just from not sleeping well."}, {"cue": "By the 5-minute mark, if a concrete next step involving the prescriber has not been proposed, the SP must say:", "line": "I don't really know what to do next about any of this."}], "closingLine": "Thanks for actually listening instead of just telling me to take the pills."}, "assessor": {"solved": ["Responds to the disclosure with a non-judgmental, rapport-building approach.", "Explicitly acknowledges the weight gain concern as valid before providing clinical information.", "Clearly explains the relapse risk of the self-reduced dose.", "Screens for early relapse warning signs and collaborates on a concrete next step involving the prescriber, without ultimatums."], "marginal": ["Acknowledges the concern but moves to clinical information too quickly.", "Explains relapse risk but does not screen for early warning signs."], "uncertain": ["Explains relapse risk but responds in a judgmental or dismissive tone toward the weight concern.", "Screens for relapse symptoms but proposes no concrete next step."], "unsolved": ["Lectures or pressures him without acknowledging his concern, damaging rapport.", "Tells him to simply resume the full dose without addressing the underlying weight concern or involving the prescriber."]}, "printedMaterials": ["Patient Record"]}, {"id": "m4", "ti": "Non-Adherence: Antidepressant", "tl": 7, "type": "adherence", "format": "patient", "sc": "Ms. Farah Haidari, 33, was started on sertraline 50 mg daily six weeks ago for major depressive disorder. She stopped taking it about a week ago because she \"felt back to normal\" and disliked some of the side effects.", "ta": "Have this conversation with Ms. Haidari using a patient-centred approach.", "cl": ["Builds rapport and asks an open-ended question about how she has been feeling since stopping", "Explores both her reasons (feeling better and side effects) without judgment", "Screens for antidepressant discontinuation symptoms since stopping abruptly (flu-like symptoms, insomnia, nausea, dizziness, sensory changes)", "Acknowledges her improvement as encouraging but explains that early symptom relief does not mean the depression has fully resolved", "Explains the recommended minimum duration of therapy (continuing at least 6-12 months after symptoms improve) to prevent relapse", "Asks which specific side effects bothered her and discusses management options or a possible adjustment instead of stopping outright", "Briefly screens for safety (mood, suicidal ideation) given the recent unplanned discontinuation", "Collaborates on a concrete next step, such as restarting under guidance with a proper tapering plan for the future"], "mn": "Feeling better at 6 weeks is the expected pharmacologic response, not permission to stop — full course is a minimum of 6-12 months after remission.", "objectives": ["To explore a patient's reasons for stopping an antidepressant early in a non-judgmental way.", "To provide accurate information on treatment duration and screen for safety."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient's care in collaboration with the patient and their circle of care.", "1.5 Monitor the patient and collaborate with the patient and their circle of care to revise the plan for the patient's care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient you have counselled before approaches you at the counter. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Farah Haidari", "gender": "Female", "age": 33, "behaviour": "Matter-of-fact and a bit dismissive of the medication's ongoing need; not in acute distress.", "profile": ["Allergies: None known", "Medical History: Major depressive disorder, diagnosed approximately six weeks ago", "Current Medications: Sertraline 50 mg daily, started six weeks ago, stopped about one week ago", "Social: Works full-time, lives with a roommate"], "otherInfo": ["She started feeling noticeably better about three to four weeks into treatment.", "The side effects that bothered her most were early nausea and some trouble sleeping.", "Since stopping about a week ago, she has noticed dizziness and 'brain zap' type sensations.", "She has not told her prescriber that she stopped taking it.", "She has no current thoughts of self-harm and describes her mood as 'pretty good' right now.", "She was not clearly told how long to continue the medication when it was started.", "She still has about three weeks of medication left in her bottle.", "She is worried about becoming 'dependent' on an antidepressant long-term."], "openingLine": "I actually stopped taking my antidepressant about a week ago — I was feeling back to normal, so I figured I didn't need it anymore.", "responses": [{"cue": "If the candidate does not ask how she has felt since stopping, the SP must add, once asked generally:", "line": "Actually, I have been feeling a bit dizzy and off the last few days, now that you mention it."}, {"cue": "If the candidate does not explain the recommended minimum duration of therapy, the SP must ask:", "line": "Wait, so I'm supposed to keep taking this even though I feel fine?"}, {"cue": "If the candidate does not screen for safety or mood, the SP must add, only if asked directly:", "line": "No, nothing like that — I've just been feeling more like myself."}, {"cue": "By the 5-minute mark, if a plan to restart or follow up has not been proposed, the SP must say:", "line": "I'm not really sure what I should do now — just leave it, or start again?"}], "closingLine": "Okay, that actually makes a lot more sense now, thanks."}, "assessor": {"solved": ["Explores her reasons for stopping without judgment and screens for discontinuation symptoms.", "Explains that early improvement reflects an expected pharmacologic response, not full resolution of depression.", "Clearly states the recommended minimum duration of therapy (6-12 months after symptom improvement).", "Screens for safety (mood/suicidal ideation) and collaborates on a concrete next step (restarting under guidance with a tapering plan)."], "marginal": ["Explains treatment duration but does not screen for discontinuation symptoms or safety.", "Screens for symptoms but gives an unclear or incomplete duration recommendation."], "uncertain": ["Explains duration of therapy but does not address her specific side-effect concerns.", "Screens for safety but provides no clear next step."], "unsolved": ["Agrees that stopping was appropriate since she feels better.", "Fails to screen for safety or mood at all despite an unplanned discontinuation."]}, "printedMaterials": ["Patient Record"]}, {"id": "m5", "ti": "Prescriber Call: Lithium-ACE Inhibitor Interaction", "tl": 7, "type": "prescribercall", "sc": "Mr. Owen Bracken, 61, has been stable on lithium 900 mg daily for bipolar disorder, with a recent level of 0.7 mmol/L. His family physician's office faxes a new prescription for ramipril 5 mg daily for newly diagnosed hypertension.", "ta": "Call the prescriber's office to discuss this new prescription using a structured framework.", "cl": ["Introduces self and pharmacy clearly, and states the reason for the call up front", "Situation: a new ACE inhibitor is being added for a patient stable on lithium", "Background: current lithium dose, most recent level, duration of stability, no other recent medication changes", "Assessment: explains specifically that ACE inhibitors reduce renal lithium clearance and can precipitate lithium toxicity, rather than a vague concern", "Recommendation: proposes an alternative antihypertensive (e.g., a dihydropyridine calcium channel blocker) or, if the ACE inhibitor is preferred, closer lithium level and renal function monitoring after initiation", "Confirms who will follow up with the patient and by when", "Is collaborative and respectful, not confrontational", "Documents the call and its outcome"], "mn": "NSAIDs and ACE inhibitors/ARBs both raise lithium levels by reducing renal clearance — caffeine, by contrast, lowers them.", "format": "hp", "objectives": ["To identify and explain a drug-related problem.", "To recommend an appropriate solution."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient’s care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy. A new prescription has been faxed for a patient who is stable on an existing therapy. You have identified a potential drug-related problem. Call the prescriber's office; a health professional there may speak with you as needed. You are not required to dispense the prescription. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Health Professional", "name": "Dr. Priya Anand", "gender": "Female", "age": "Any", "behaviour": "Open to suggestions, willing to discuss the concern.", "profile": ["Allergies: None known", "Medical History: Bipolar disorder (lithium-stabilized); newly diagnosed hypertension", "Current Medications: Lithium carbonate 900 mg daily; new ramipril 5 mg daily (just prescribed)"], "otherInfo": ["Mr. Bracken's most recent lithium level (0.7 mmol/L) was drawn 3 weeks ago and he has been on the same dose for over a year.", "His blood pressure at today's visit was 148/92 mmHg, prompting the new prescription.", "He has had no recent illness, vomiting, or diarrhea that could otherwise affect his lithium level.", "His renal function was last checked 3 weeks ago and was normal (eGFR 88 mL/min/1.73m²).", "You are willing to order a repeat lithium level and renal panel 5-7 days after starting the new drug if asked.", "You are willing to consider an alternative agent if the candidate provides a specific, reasoned option.", "The patient has a follow-up booked with your office in 4 weeks regardless of what is decided today."], "openingLine": "Hello, this is Dr. Anand's office returning your call about Mr. Bracken's new prescription. What can I help you with?", "responses": [{"cue": "If the candidate raises a concern without naming the specific interacting drug pair, the HP must ask:", "line": "Which medications are you concerned about, exactly?"}, {"cue": "If the candidate identifies the interaction but does not explain the mechanism or expected effect, the HP must ask:", "line": "Can you tell me more about why that's a problem for him?"}, {"cue": "If the candidate has not offered a recommendation after explaining the problem, the HP must ask:", "line": "So what would you suggest instead?"}, {"cue": "If the candidate recommends only closer monitoring without addressing the drug choice, the HP must ask:", "line": "Should I be changing anything about his blood pressure medication, or just watching his lithium level?"}], "closingLine": "Thank you for calling — I'll make a note of this in his chart."}, "assessor": {"solved": ["Identifies the potential lithium-ACE inhibitor (ramipril) interaction.", "Explains the mechanism: ACE inhibitors reduce renal clearance of lithium, raising lithium levels.", "Explains the probable outcome: risk of lithium toxicity.", "Recommends an acceptable option: an alternative antihypertensive (e.g., a dihydropyridine calcium channel blocker) OR continuing ramipril with closer lithium level and renal function monitoring.", "Confirms a follow-up plan and documents the call."], "marginal": ["Identifies the interaction but explains the mechanism or outcome only briefly.", "Recommends an acceptable option but does not specify a monitoring interval or clear alternative.", "Communicates respectfully but the discussion is less thorough."], "uncertain": ["Identifies the interaction but does not clearly explain mechanism or outcome.", "Recommends increased monitoring only, without addressing whether the ACE inhibitor is appropriate."], "unsolved": ["Does not identify the lithium-ACE inhibitor interaction.", "Incorrectly explains the interaction (e.g., states ACE inhibitors lower lithium levels).", "Agrees to fill ramipril as written without discussing the interaction or monitoring."]}, "printedMaterials": ["Drug Monographs", "Patient Record", "Faxed Prescription"]}, {"id": "m6", "ti": "Prescriber Call: Gabapentin Accumulation in Declining Renal Function", "tl": 7, "type": "prescribercall", "sc": "Mrs. Beulah Ortiz, 74, has been taking gabapentin 600 mg three times daily for diabetic peripheral neuropathy. Her latest labs show her eGFR has fallen from 55 to 24 mL/min/1.73m². Her daughter calls the pharmacy reporting her mother has become unusually drowsy and unsteady on her feet this week.", "ta": "Call the prescriber's office to discuss this concern using a structured framework.", "cl": ["Introduces self and pharmacy clearly, and states the reason for the call up front", "Situation: new sedation and unsteadiness in a patient on an unchanged gabapentin dose", "Background: notes gabapentin is renally eliminated with no hepatic metabolism, and reports the recent drop in eGFR alongside the current dosing frequency", "Assessment: states the specific concern — gabapentin accumulation from declining renal function likely causing sedation and ataxia, with fall risk", "Recommendation: proposes a renally adjusted dose or frequency reduction and asks whether repeat renal function testing is planned", "Confirms the plan for reassessing the patient and who communicates it to the family", "Is collaborative and respectful, not confrontational", "Documents the call and communicates the outcome to the daughter"], "mn": "Gabapentin is roughly 90% renally eliminated unchanged — a falling eGFR with new sedation or ataxia in an older adult should immediately raise suspicion of drug accumulation.", "format": "hp", "objectives": ["To identify and explain a drug-related problem.", "To recommend an appropriate solution."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient’s care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy. A patient's daughter has called reporting new drowsiness and unsteadiness. You have identified a potential drug-related problem involving the patient's current therapy in the context of declining renal function. Call the prescriber's office; a health professional there may speak with you as needed. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Health Professional", "name": "Dr. Samuel Whitcombe", "gender": "Male", "age": "Any", "behaviour": "Willing to listen, slightly rushed but attentive.", "profile": ["Allergies: None known", "Medical History: Type 2 diabetes with diabetic peripheral neuropathy; declining renal function (recent eGFR drop)", "Current Medications: Gabapentin 600 mg three times daily; metformin (dose previously adjusted for renal function)"], "otherInfo": ["The eGFR fell from 55 to 24 mL/min/1.73m² over the past two months, found on routine bloodwork.", "The gabapentin dose has not been changed in over a year.", "The daughter reports her mother had one fall at home this week, though no injury.", "You have not yet seen the patient in person since the new labs came back.", "You are open to a renal function recheck and to reassessing gabapentin dosing today.", "No other new medications have been started recently."], "openingLine": "Hi, this is Dr. Whitcombe's office. I understand you're calling about Mrs. Ortiz — what's going on?", "responses": [{"cue": "If the candidate reports the symptoms without connecting them to a specific drug, the HP must ask:", "line": "Do you think this is related to one of her medications?"}, {"cue": "If the candidate identifies gabapentin as the issue but does not explain why, the HP must ask:", "line": "Why would that be a problem now if her dose hasn't changed?"}, {"cue": "If the candidate has not offered a specific recommendation, the HP must ask:", "line": "What would you like me to do about her dose?"}, {"cue": "If the candidate only recommends stopping the drug rather than adjusting it, the HP must ask:", "line": "Is there no way to keep her on something for the neuropathy pain?"}], "closingLine": "Thanks for catching this — I'll adjust the order now."}, "assessor": {"solved": ["Identifies gabapentin accumulation as the likely cause of new sedation and unsteadiness.", "Explains the mechanism: gabapentin is renally eliminated and the recent drop in eGFR reduces its clearance.", "Explains the outcome: elevated gabapentin levels causing sedation, ataxia, and fall risk.", "Recommends an acceptable option: a renally adjusted dose or reduced frequency, with repeat renal function testing.", "Confirms a plan for reassessing the patient and communicating with the daughter."], "marginal": ["Identifies gabapentin as the cause but explains the renal mechanism only briefly.", "Recommends a dose reduction but does not specify renal-adjusted dosing or a monitoring plan."], "uncertain": ["Identifies a possible medication-related cause but does not clearly connect it to renal function.", "Recommends stopping gabapentin without offering an alternative for neuropathic pain or a monitoring plan."], "unsolved": ["Does not identify gabapentin accumulation as the cause of the symptoms.", "Attributes the symptoms solely to age or unrelated causes without addressing the renal-gabapentin link.", "Recommends continuing the same dose without any adjustment or monitoring."]}, "printedMaterials": ["Drug Monographs", "Patient Record", "Lab Results"]}, {"id": "m7", "ti": "Refusal: Altered Controlled-Drug Prescription", "tl": 7, "type": "refusal", "sc": "A man presents a written prescription for clonazepam 0.5 mg where the quantity appears to have been changed from \"30\" to \"90\" in different ink, and the initials beside the change do not match the rest of the script.", "ta": "Handle this situation appropriately, balancing empathy with your professional and regulatory obligations.", "cl": ["Greets the patient calmly and privately, without immediately accusing him of wrongdoing", "Clearly explains that the pharmacy cannot fill a prescription with an alteration that cannot be verified as authorized by the prescriber", "Explains the reasoning in plain, non-accusatory language rather than a blunt refusal", "Contacts the prescriber's office directly to verify the intended quantity before proceeding with any fill", "Sensitively screens for safety concerns (withdrawal risk, diversion) without being accusatory", "Retains and documents the original prescription per policy rather than returning it if forgery is suspected", "Offers a concrete alternative, such as waiting while the office is contacted or dispensing the verified original quantity", "Documents the interaction thoroughly, including the discrepancy and the steps taken", "Reports to the regulatory authority if forgery is confirmed"], "mn": "An alteration in different ink or an unverifiable initial beside a controlled-drug quantity is a verify-before-you-fill trigger, not grounds for an on-the-spot accusation.", "format": "patient", "objectives": ["To handle a suspected prescription alteration appropriately.", "To balance patient care with legal and professional obligations."], "competencies": [{"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements.", "5.2 Apply ethical principles to practice."]}, {"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will present a written prescription for a controlled substance. Assess the situation and respond as you would in practice, balancing empathy with your professional and regulatory obligations. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Marcus Delaney", "gender": "Male", "age": 34, "behaviour": "Initially defensive and a little anxious; becomes more cooperative if treated respectfully.", "profile": ["Allergies: None known", "Medical History: Generalized anxiety disorder", "Current Medications: clonazepam 0.5 mg, prescribed quantity 30, last filled 3 weeks ago"], "otherInfo": ["He says he 'ran out early' and needs the medication today.", "He states the doctor's office is closed for the rest of the day.", "If asked directly whether he changed the quantity, he becomes flustered and does not give a clear answer.", "He admits, if pressed gently, that he has been taking more than prescribed because his anxiety has worsened recently.", "He has not sought any other source for the medication.", "He does not appear to be in acute withdrawal (no tremor, sweating, or agitation observed).", "He is willing to wait while the pharmacy contacts the prescriber's office."], "openingLine": "Hi, I need to get this filled today — I'm out and I really need it.", "responses": [{"cue": "If the candidate fills the prescription without addressing the alteration, the SP must say:", "line": "So we're all good then? I can get all 90?"}, {"cue": "If the candidate directly accuses him of forgery, the SP must say:", "line": "Whoa, I didn't do anything — why are you accusing me?"}, {"cue": "If the candidate refuses without offering to verify with the prescriber, the SP must ask:", "line": "So what am I supposed to do now? I need this."}, {"cue": "If the candidate does not ask about his current use pattern, the SP must volunteer:", "line": "Look, I've just been taking a bit more than I should lately — it's been a rough few weeks."}], "closingLine": "Okay... thanks for at least trying to help me sort this out."}, "assessor": {"solved": ["Explains calmly and non-accusatorially that the alteration cannot be verified and the prescription cannot be filled as presented.", "Contacts the prescriber's office to verify the intended quantity before taking any action.", "Sensitively screens for safety concerns (overuse, withdrawal risk) without accusing him of wrongdoing.", "Retains and documents the original prescription per policy and offers a concrete alternative (e.g., wait for verification, dispense the verified quantity)."], "marginal": ["Explains that the prescription cannot be filled as presented, but the explanation is less clear or somewhat accusatory in tone.", "Contacts the prescriber's office but does not adequately reassure the patient in the meantime.", "Screens for safety concerns only briefly."], "uncertain": ["Refuses to fill the prescription but does not attempt to verify with the prescriber or offer an alternative.", "Does not screen for safety/overuse concerns."], "unsolved": ["Fills the prescription for the altered quantity without verification.", "Directly accuses the patient of forgery without evidence or verification.", "Refuses the prescription and returns the original document to the patient despite suspected forgery."]}, "printedMaterials": ["Written Prescription (with alteration)", "Patient Record", "College Verification Policy Reference"]}, {"id": "m8", "ti": "Medication Error: Wrong Strength Dispensed", "tl": 7, "type": "error", "sc": "Mrs. Anh Pham, 45, returns to the pharmacy after two days on what was supposed to be sertraline 50 mg daily, reporting she feels unusually jittery and nauseated. On review, the pharmacy dispensed sertraline 100 mg tablets in error.", "ta": "Manage this medication error appropriately with Mrs. Pham.", "cl": ["Acknowledges the error directly and honestly as soon as it is identified, without minimizing or deflecting", "Apologizes sincerely without excessive self-blame or alarming her unnecessarily", "Assesses her current symptoms and rules out signs of serious toxicity before reassuring her", "Gives clear clinical guidance on what to do now regarding today's and future doses", "Contacts the prescriber to inform them of the error and confirm the intended ongoing dose", "Corrects the prescription and provides the correct-strength medication at no charge", "Documents the error per the pharmacy's incident-reporting process", "Briefly explains what will change to reduce recurrence (e.g., an independent double-check at final verification) without being defensive", "Checks her understanding and offers follow-up contact if symptoms worsen"], "mn": "Dispensing errors must be disclosed fully and promptly — minimizing or deflecting blame is itself a professionalism failure, separate from the clinical error.", "format": "patient", "objectives": ["To disclose and manage a dispensing error appropriately.", "To ensure patient safety and prevent recurrence."], "competencies": [{"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements.", "5.2 Apply ethical principles to practice."]}, {"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.4 Implement a plan for the patient’s care in collaboration with the patient and their circle of care.", "1.5 Monitor the patient and collaborate with the patient and their circle of care to revise the plan for the patient’s care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy. A patient returns two days after picking up a new prescription, reporting side effects. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Anh Pham", "gender": "Female", "age": 45, "behaviour": "Worried and a little frustrated, but not hostile; becomes reassured with clear, honest communication.", "profile": ["Allergies: None known", "Medical History: Major depressive disorder, newly diagnosed", "Current Medications: sertraline — prescribed 50 mg daily, dispensed in error as 100 mg tablets 2 days ago"], "otherInfo": ["She has taken two doses of the 100 mg tablets (one each of the past two mornings).", "She describes the jitteriness and nausea as uncomfortable but not severe — no chest pain, fainting, or serious bleeding.", "She has 28 of the 100 mg tablets remaining in the bottle.", "This is her first antidepressant; she was understandably anxious about starting it in the first place.", "She wants to know if the mistake will affect how well the medication works long term.", "She has not contacted her prescriber herself.", "She is willing to come back for the correct medication today."], "openingLine": "Hi, I picked up my new prescription here two days ago and I've been feeling really jittery and sick to my stomach — is that normal?", "responses": [{"cue": "If the candidate does not proactively identify that an error occurred, the SP must ask:", "line": "Is there something wrong with what I was given?"}, {"cue": "If the candidate discloses the error but does not apologize, the SP must ask:", "line": "How did this happen?"}, {"cue": "If the candidate does not address whether she is in danger, the SP must ask:", "line": "Is what I took going to hurt me?"}, {"cue": "If the candidate does not mention correcting the prescription or replacing the medication, the SP must ask:", "line": "So what do I do about the pills I have at home?"}], "closingLine": "Thank you for being upfront with me about this."}, "assessor": {"solved": ["Discloses the dispensing error directly and honestly, with a sincere apology.", "Assesses current symptoms and rules out signs of serious toxicity before reassuring her.", "Gives clear guidance on today's and future dosing and provides the correct-strength medication at no charge.", "Contacts the prescriber to inform them of the error and confirm the ongoing dose.", "Documents the error per the incident-reporting process and briefly explains a step to reduce recurrence."], "marginal": ["Discloses the error but the apology or explanation feels rushed or incomplete.", "Assesses symptoms but does not clearly rule out serious toxicity before reassuring her.", "Provides the correct medication but does not contact the prescriber or explain a prevention step."], "uncertain": ["Discloses that an error occurred but is vague about what happened or why.", "Addresses the immediate dosing question but does not follow through on prescriber notification or documentation."], "unsolved": ["Does not disclose the error, or minimizes/deflects responsibility for it.", "Advises her to continue taking the 100 mg tablets without correcting the prescription.", "Fails to assess for signs of toxicity despite her reported symptoms."]}, "printedMaterials": ["Patient Record", "Dispensing Log", "Incident Report Form"]}, {"id": "m9", "ti": "Medication Error: Wrong-Patient Bag Mix-Up", "tl": 7, "type": "error", "sc": "Two patients with similar names, Robert Sinclair and Robert St. Clair, were given each other's prescription bags at pickup. Mr. Sinclair calls the next day saying the bottle contains tablets he doesn't recognize, labeled with a name similar to his own.", "ta": "Manage this medication error appropriately with Mr. Sinclair.", "cl": ["Acknowledges the error directly and honestly, and apologizes sincerely", "Confirms exactly what medication and how many doses he actually took from the incorrect bag", "Assesses potential harm based on the specific drug taken, checking for interactions or contraindications with his own conditions, and gives clear instructions on what to do now", "Advises him not to take any further doses from the incorrect bag and to return it to the pharmacy", "Simultaneously initiates contact with the other patient to recover his correct bag and check whether he took any doses in error", "Notifies the prescriber(s) involved if clinically relevant", "Documents the incident per the pharmacy's incident-reporting process", "Identifies the system contributor (similar patient names) and states a concrete prevention step, such as independent identity/date-of-birth verification at pickup", "Closes with safety-netting: symptoms to watch for and when to seek urgent care"], "mn": "A similar-name mix-up needs a two-sided fix — both patients' bags and doses-taken must be traced, not just the one who happened to call first.", "format": "patient", "objectives": ["To disclose and manage a dispensing error involving a wrong-patient mix-up.", "To ensure the safety of both patients involved."], "competencies": [{"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements.", "5.2 Apply ethical principles to practice."]}, {"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.4 Implement a plan for the patient’s care in collaboration with the patient and their circle of care.", "1.5 Monitor the patient and collaborate with the patient and their circle of care to revise the plan for the patient’s care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.4 Document pharmacy care and services and maintain pharmacy records."]}], "instructions": "You are working in a community pharmacy. A patient calls reporting he may have received someone else's prescription bag. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Robert Sinclair", "gender": "Male", "age": 58, "behaviour": "Concerned and a bit anxious about having taken the wrong medication; cooperative.", "profile": ["Allergies: Penicillin (rash)", "Medical History: Hypertension", "Current Medications: amlodipine 5 mg daily (his own, correct medication)"], "otherInfo": ["He took one dose of the unfamiliar tablets last night before realizing the label name looked slightly different from his own.", "The bottle is labeled for 'Robert St. Clair' with a medication he does not recognize (a sulfonylurea, glyburide).", "He has no history of diabetes and has never taken glyburide before.", "He feels fine today — no symptoms of low blood sugar (shakiness, sweating, confusion).", "He still has his own correct bag at home, unopened, that he has not yet started.", "He is willing to bring the incorrect bag back to the pharmacy.", "He does not know Robert St. Clair personally."], "openingLine": "Hi, I picked up my prescription yesterday but the bottle has a slightly different name on it than mine, and I don't recognize the pills — I think I took one last night.", "responses": [{"cue": "If the candidate does not ask what he actually took, the SP must say:", "line": "I'm not totally sure what's in the bottle — should I be worried?"}, {"cue": "If the candidate does not advise him to stop taking the incorrect medication, the SP must ask:", "line": "Should I keep taking these, or what?"}, {"cue": "If the candidate does not mention the other patient, the SP must ask:", "line": "What about the other guy — did he get my pills?"}, {"cue": "If the candidate does not give any safety-netting advice, the SP must ask:", "line": "Is there anything I should watch out for since I took one of these?"}], "closingLine": "Okay, thanks for helping me sort this out."}, "assessor": {"solved": ["Discloses the error and apologizes sincerely.", "Confirms exactly what medication and how many doses he took from the incorrect bag.", "Assesses potential harm from the glyburide dose taken (hypoglycemia risk) and gives clear instructions on what to do now, including stopping the incorrect medication.", "Simultaneously initiates contact with the other patient to recover his correct bag and check for doses taken in error.", "Documents the incident and identifies the similar-name system contributor with a concrete prevention step."], "marginal": ["Discloses the error and confirms what was taken, but harm assessment is less thorough.", "Advises stopping the incorrect medication but does not clearly address contacting the other patient."], "uncertain": ["Discloses the error but does not confirm details of what was taken or assess for potential harm.", "Addresses this patient's situation but takes no action regarding the other patient involved."], "unsolved": ["Does not disclose the error or minimizes the mix-up.", "Advises him to continue taking the incorrect medication.", "Takes no steps to trace or recover the other patient's bag."]}, "printedMaterials": ["Patient Record", "Dispensing Log", "Incident Report Form"]}, {"id": "m10", "ti": "Assessment: Uncomplicated UTI Self-Referral", "tl": 7, "type": "assessment", "sc": "Ms. Danielle Okoro, 29, presents asking to be assessed for a urinary tract infection. She reports burning with urination and increased frequency for the past day, with no fever, flank pain, or vaginal discharge, and no prior UTI history. She confirms she is not pregnant.", "ta": "Assess Ms. Okoro using an appropriate framework and determine next steps.", "cl": ["Introduces self, confirms identity, and ensures privacy for a sensitive assessment", "Takes a focused history: onset, character, frequency/urgency, presence of blood in urine, vaginal symptoms", "Screens for upper tract or systemic red flags: fever, chills, flank or back pain, nausea/vomiting", "Screens for exclusions to self-referral assessment: pregnancy, male sex, immunocompromise, indwelling catheter, recurrent or relapsing infection, known renal abnormality", "Reviews allergy history and current medications before considering empiric antibiotic therapy", "States a working assessment of uncomplicated lower UTI and an appropriate first-line treatment option with rationale", "Explains the expected course, hydration advice, and timeframe for improvement", "Provides clear safety-netting: red flags requiring escalation, such as fever, flank pain, or symptoms not improving within 48 hours", "Checks her understanding and confirms a follow-up plan"], "mn": "Fever, flank pain, or male sex turns \"uncomplicated cystitis\" into a red flag needing referral rather than self-referral treatment.", "format": "patient", "objectives": ["To assess a patient for an uncomplicated urinary tract infection.", "To determine appropriate treatment or referral."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient.", "1.3 Develop a plan for the patient’s care in collaboration with the patient and their circle of care.", "1.4 Implement a plan for the patient’s care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy authorized to assess and prescribe for minor ailments. A patient will come in requesting assessment for a urinary tract infection. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Danielle Okoro", "gender": "Female", "age": 29, "behaviour": "Slightly embarrassed but cooperative and direct when asked specific questions.", "profile": ["Allergies: None known", "Medical History: No prior UTIs; otherwise healthy", "Current Medications: Combined oral contraceptive pill"], "otherInfo": ["Symptoms started yesterday afternoon: burning with urination and needing to go more often than usual.", "No blood in the urine, no vaginal discharge or itching, no new sexual partner recently.", "No fever, chills, back or flank pain, nausea, or vomiting.", "She confirmed she is not pregnant (negative home test last week for an unrelated reason) and has a regular menstrual cycle.", "She has no known kidney problems, no catheter, and is not immunocompromised.", "She drinks minimal water on a typical workday and works a desk job.", "She would prefer to avoid a walk-in clinic visit if possible given her schedule."], "openingLine": "Hi, I think I might have a bladder infection — it burns when I pee and I keep having to go. Can you help me with that here?", "responses": [{"cue": "If the candidate does not ask about fever, flank pain, or other red flags, the SP must volunteer:", "line": "Should I be worried about anything else, like a fever or back pain?"}, {"cue": "If the candidate does not ask about pregnancy status, the SP must say:", "line": "I should mention — I'm not pregnant, in case that matters."}, {"cue": "If the candidate recommends treatment without discussing what to expect, the SP must ask:", "line": "How soon should this start working?"}, {"cue": "If the candidate does not mention when to seek further care, the SP must ask:", "line": "What if it's not better in a few days?"}], "closingLine": "Great, thank you — that's really helpful."}, "assessor": {"solved": ["Takes a focused history covering onset, character, and associated symptoms, and confirms absence of upper tract/systemic red flags.", "Confirms exclusion criteria are absent: not pregnant, no fever/flank pain, no catheter, not immunocompromised, no recurrent infection.", "States a working assessment of uncomplicated lower UTI and recommends an appropriate first-line empiric antibiotic with correct dose and duration.", "Provides clear safety-netting: red flags requiring escalation (fever, flank pain, symptoms not improving within 48 hours)."], "marginal": ["Takes a history and confirms most red flags/exclusions, but misses one (e.g., does not confirm pregnancy status).", "Recommends appropriate therapy but with an incomplete dose, duration, or hydration advice."], "uncertain": ["Takes a partial history and recommends treatment without fully confirming red flags are absent.", "Recommends treatment but gives no safety-netting or follow-up advice."], "unsolved": ["Does not screen for red flags or exclusion criteria at all before recommending treatment.", "Recommends antibiotic therapy despite an unassessed red flag (e.g., without asking about pregnancy or fever).", "Fails to recognize the need for referral if red flags were in fact present."]}, "printedMaterials": ["Minor Ailments Prescribing Guide", "Patient Record", "Assessment Form"]}, {"id": "m11", "ti": "Assessment: Dyspepsia with Red Flags", "tl": 7, "type": "assessment", "sc": "Mr. Harold Whitfield, 57, asks for something for \"heartburn and an upset stomach\" that has been going on for about six weeks. On further questioning, he also mentions unintentional weight loss and increasing difficulty swallowing solid food.", "ta": "Assess Mr. Whitfield using an appropriate framework and determine next steps.", "cl": ["Introduces self and takes a focused history of onset, character, timing, and aggravating/relieving factors", "Actively elicits and identifies red flags: new onset over age 50 with unexplained weight loss and difficulty swallowing", "Screens for additional red flags: blood in stool or vomit, black tarry stools, persistent vomiting, severe abdominal pain", "Reviews his medication history for contributing agents (e.g., NSAIDs, ASA, bisphosphonates) and relevant social history (smoking, alcohol)", "Recognizes that this combination of red flags makes self-care or OTC treatment inappropriate", "Clearly explains to the patient, without causing undue alarm, why referral is needed to rule out serious underlying causes", "Refers promptly to his physician for urgent assessment rather than recommending an antacid or a PPI trial", "Checks his understanding and offers to communicate with his physician's office if helpful"], "mn": "Weight loss plus difficulty swallowing in a patient over 50 with new dyspepsia is an automatic referral, not a PPI trial.", "format": "patient", "objectives": ["To assess a patient presenting with dyspepsia.", "To recognize red flags requiring referral rather than self-care."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.1 Obtain relevant patient information.", "1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient.", "1.4 Implement a plan for the patient’s care in collaboration with the patient and their circle of care."]}, {"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient will come in asking for advice about ongoing stomach symptoms. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Harold Whitfield", "gender": "Male", "age": 57, "behaviour": "Downplays his symptoms initially; a bit stoic, reluctant to see this as serious.", "profile": ["Allergies: None known", "Medical History: Osteoarthritis of both knees", "Current Medications: ibuprofen 400 mg, taken several times a week for joint pain; occasional acetaminophen"], "otherInfo": ["Symptoms of heartburn and upset stomach have been present for about six weeks, worse after meals.", "He has lost roughly 10 lbs over the past two months without trying.", "He has noticed food, especially solids like bread and meat, feels like it 'gets stuck' going down.", "He has not noticed blood in his stool or vomit, and stool colour is normal, though he admits he hasn't looked closely.", "He has been taking ibuprofen regularly for his knees for the past year.", "He smokes about half a pack of cigarettes a day and has a beer most evenings.", "He was hoping to just grab 'something for heartburn' without seeing a doctor because he dislikes going to appointments."], "openingLine": "I've had heartburn and an upset stomach for a while now — can you recommend something over the counter?", "responses": [{"cue": "If the candidate does not ask about associated symptoms like weight loss or swallowing difficulty, the SP must volunteer:", "line": "I guess I should mention, food's been kind of getting stuck going down lately, and I've lost some weight too."}, {"cue": "If the candidate recommends an OTC product without addressing the red flags, the SP must ask:", "line": "So something over the counter will be fine for this, then?"}, {"cue": "If the candidate recommends referral, the SP must ask:", "line": "Is this something serious? Do I really need to see a doctor for heartburn?"}, {"cue": "If the candidate does not ask about his ibuprofen use, the SP must volunteer:", "line": "I do take ibuprofen pretty often for my knees, if that matters."}], "closingLine": "Alright, I suppose I should get that checked out, then. Thank you."}, "assessor": {"solved": ["Takes a focused history of the dyspepsia and actively elicits the red flags: unintentional weight loss and dysphagia.", "Screens for additional red flags (GI bleeding, persistent vomiting, severe pain) and relevant contributors (NSAID use, smoking, alcohol).", "Recognizes that these red flags make self-care/OTC treatment inappropriate.", "Clearly and calmly explains the need for referral and refers promptly to his physician for urgent assessment."], "marginal": ["Identifies at least one red flag but the explanation of the need for referral is less thorough or somewhat alarming.", "Refers appropriately but does not review contributing medications (e.g., ibuprofen) or social history."], "uncertain": ["Elicits the red flags only after being prompted by the patient, and referral advice is unclear or delayed.", "Recommends a short OTC trial in addition to referral without clearly prioritizing urgent assessment."], "unsolved": ["Does not elicit the weight loss or swallowing difficulty at all.", "Recommends an antacid, H2-blocker, or PPI trial without referral despite the red flags.", "Reassures the patient that this is likely benign without any escalation."]}, "printedMaterials": ["CPS Document (Dyspepsia)", "Patient Record", "Non-prescription Products (on shelf)"]}, {"id": "m12", "ti": "Difficult Conversation: Bereavement and Sedative Overuse", "tl": 7, "type": "difficult", "sc": "Mrs. Carol Jennings, 70, lost her husband of 45 years three months ago. She has been requesting early refills of her lorazepam 1 mg, prescribed PRN for anxiety, and admits she has been taking it most nights \"just to get some peace.\"", "ta": "Have this conversation with Mrs. Jennings.", "cl": ["Lets her speak fully about her loss before responding, without immediately jumping to the medication issue", "Validates her grief and the difficulty of the past three months explicitly, before discussing anything clinical", "Gently raises the pattern of increased lorazepam use once rapport is established, without shaming her", "Explores what the medication is helping with (sleep, anxiety, loneliness) to understand the underlying need", "Provides balanced information on the risks of regular benzodiazepine use in older adults (falls, dependence, cognitive effects) only once she feels heard", "Offers appropriate support resources, such as grief counselling or a bereavement support group, and suggests follow-up with her prescriber, rather than simply refusing the refill", "Collaborates on one concrete next step, such as a follow-up appointment to reassess her anxiety and sleep", "Closes with an open door for further conversation and avoids making her feel judged"], "mn": "Grief with escalating PRN benzodiazepine use is a difficult-conversation station, not a refusal station — validate the emotion first, address safety second.", "format": "patient", "objectives": ["To have a supportive, non-judgmental conversation about a sensitive medication-use concern.", "To balance empathy with patient safety."], "competencies": [{"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties."]}, {"code": "5", "label": "Professionalism", "elements": ["5.2 Apply ethical principles to practice."]}, {"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient."]}], "instructions": "You are working in a community pharmacy. A patient with a recent bereavement will come in requesting an early refill of a sedative medication. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Carol Jennings", "gender": "Female", "age": 70, "behaviour": "Grieving, initially guarded and a little defensive about her medication use, softens once she feels heard.", "profile": ["Allergies: None known", "Medical History: Generalized anxiety, situational, following recent bereavement", "Current Medications: lorazepam 1 mg PRN for anxiety, prescribed after her husband's passing"], "otherInfo": ["Her husband of 45 years passed away three months ago from a sudden cardiac event.", "She lives alone now for the first time since her twenties and describes the house as 'too quiet.'", "She has been taking lorazepam most nights for the past month, more than the occasional PRN use it was originally intended for.", "She has had one instance of feeling unsteady getting up at night, though no fall.", "She has not told her family doctor about how often she has been using it.", "Her adult children live out of town and she does not want to worry them.", "She has not considered counselling before and is unsure whether it would help her.", "She is worried the pharmacist will refuse to give her any more medication."], "openingLine": "I need to get my lorazepam refilled again — I know it's a bit early, but I really haven't been sleeping.", "responses": [{"cue": "If the candidate moves straight to discussing the medication without acknowledging her loss, the SP must say (with emotion):", "line": "It's just been so hard since my husband passed."}, {"cue": "If the candidate raises the frequency of use in a judgmental way, the SP must say:", "line": "I'm not trying to abuse it, I just need something to get through the nights."}, {"cue": "If the candidate does not explore what the medication is helping with, the SP must volunteer:", "line": "The house is just so quiet now — I think that's really what I can't stand."}, {"cue": "If the candidate simply refuses the early refill without offering support, the SP must ask:", "line": "So what am I supposed to do, then?"}], "closingLine": "Thank you for listening — I think I needed that more than the pills, honestly."}, "assessor": {"solved": ["Lets her speak about her loss and validates her grief explicitly before addressing the medication.", "Gently raises the pattern of increased lorazepam use without shaming her, and explores the underlying need (sleep, anxiety, loneliness).", "Provides balanced information on the risks of regular benzodiazepine use in older adults once she feels heard.", "Offers appropriate support resources (grief counselling/support group) and suggests follow-up with her prescriber, collaborating on one concrete next step."], "marginal": ["Validates her grief but transitions to the medication discussion somewhat abruptly.", "Raises the usage pattern and risks but offers only generic support resources without a concrete next step."], "uncertain": ["Acknowledges her loss briefly but focuses mainly on the medication concern.", "Discusses risks of benzodiazepine use but does not offer support resources or a follow-up plan."], "unsolved": ["Refuses the early refill without acknowledging her grief or exploring the underlying need.", "Dismisses or minimizes her loss.", "Provides the refill without addressing the pattern of use or safety risks at all."]}, "printedMaterials": ["Patient Record", "Community Grief Support Resource List"]}, {"id": "m13", "ti": "Difficult Conversation: Family Conflict Over Palliative Pain Control", "tl": 7, "type": "difficult", "sc": "Mr. Desmond Okafor, 81, is in the palliative phase of advanced cancer and has clearly told the care team he wants his opioid dose kept as-is because it controls his pain well. His son calls the pharmacy insisting the dose be reduced because he is worried his father is \"too sedated and not himself.\"", "ta": "Have this conversation with the son.", "cl": ["Lets the son express his concerns fully before responding", "Validates his fear and distress about seeing his father sedated, without dismissing it", "Clarifies that the patient has expressed his own wishes and has the capacity to make this decision, respecting patient autonomy as the primary consideration", "Explains, in balanced and non-alarming language, that some sedation can be an expected trade-off in palliative pain control that the patient himself has accepted", "Does not unilaterally change the dose based on the son's request alone, and explains that any change requires discussion with the patient and the care team", "Offers to facilitate a joint conversation between the son, the patient, and the care team to address the concern", "Screens for any new safety concerns the son describes that could suggest true overdose rather than expected sedation, and escalates appropriately if so", "Closes with a concrete next step and offers ongoing support or resources for the family"], "mn": "When a competent patient's wishes and a family member's wishes conflict, the patient's autonomy governs — the pharmacist's role is to facilitate communication, not to silently comply with either side.", "format": "patient", "objectives": ["To manage a family conflict regarding a competent patient's palliative care decisions.", "To uphold patient autonomy while addressing the family's concerns."], "competencies": [{"code": "3", "label": "Communication and Collaboration", "elements": ["3.1 Use effective communication skills.", "3.2 Work in partnership with the patient.", "3.3 Collaborate with pharmacy colleagues, other health professionals and other involved parties."]}, {"code": "5", "label": "Professionalism", "elements": ["5.2 Apply ethical principles to practice."]}, {"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient’s health status and unique needs, goals, and preferences, in partnership with the patient."]}], "instructions": "You are working in a community pharmacy that supports a patient receiving palliative care at home. A family member will call or come in with concerns about the patient's opioid therapy. Assess the situation and respond as you would in practice. Time Frame: You have 7 minutes to complete this station.", "participant": {"role": "Simulated Participant", "name": "Emeka Okafor", "gender": "Male", "age": 50, "behaviour": "Anxious and protective, speaks quickly, becomes tearful when discussing his father's condition.", "profile": ["Allergies: None known", "Medical History: Advanced cancer, palliative phase (patient: his father, Desmond Okafor)", "Current Medications: Long-acting and breakthrough opioid therapy for cancer pain, dose recently optimized and stable"], "otherInfo": ["Emeka has been staying with his father for the past two weeks to help with caregiving.", "He describes his father as sleeping most of the day and sometimes seeming confused when he wakes.", "His father has told the care team clearly and repeatedly that he wants his pain controlled and accepts feeling drowsy as a trade-off.", "Emeka has not personally spoken with the palliative care team about his concerns before calling the pharmacy.", "He has not observed any signs of overdose such as slowed or shallow breathing, and his father can still recognize him and respond to questions, just slowly.", "He is afraid that reducing the dose would cause his father unnecessary pain, but he is more afraid of 'losing him early to the medication.'", "He mentions his mother passed away in a hospital in pain years ago, which is shaping his fear now."], "openingLine": "I need you to reduce my dad's pain medication — he's so out of it all the time, he's not even himself anymore.", "responses": [{"cue": "If the candidate dismisses his concern quickly, the SP must say (with emotion):", "line": "You're not the one watching him sleep his life away."}, {"cue": "If the candidate does not acknowledge his father's own wishes, the SP must ask:", "line": "Doesn't it matter what I think, as his son?"}, {"cue": "If the candidate agrees to change the dose without involving the patient or care team, the SP must ask:", "line": "So you'll just lower it today, then?"}, {"cue": "If the candidate does not ask about specific safety concerns, the SP must volunteer:", "line": "I haven't noticed his breathing being weird or anything, if that's what you mean."}], "closingLine": "Okay... I just want what's best for him. Thank you for hearing me out."}, "assessor": {"solved": ["Lets the son express his concerns fully and validates his fear and distress without dismissing it.", "Clarifies that the patient has expressed his own wishes and has the capacity to make this decision, and does not unilaterally change the dose based on the son's request alone.", "Explains, in balanced and non-alarming language, that some sedation can be an expected and accepted trade-off in palliative pain control.", "Screens for true safety concerns (e.g., respiratory depression) and offers to facilitate a joint conversation between the son, the patient, and the care team."], "marginal": ["Validates his concern but the explanation of patient autonomy/expected sedation is less thorough.", "Does not change the dose unilaterally but does not clearly offer to facilitate further communication."], "uncertain": ["Acknowledges the son's concern only briefly before moving to clinical explanation.", "Explains expected sedation but does not address the conflict between the son's wishes and the patient's wishes."], "unsolved": ["Agrees to reduce the opioid dose based solely on the son's request without involving the patient or care team.", "Dismisses the son's concern entirely without validation or explanation.", "Fails to screen for genuine safety concerns despite the son's description of increased sedation and confusion."]}, "printedMaterials": ["Patient Record", "Palliative Care Plan Summary"]}, {"id": "sr1", "ti": "Screening New Prescriptions: General Practice", "tl": 7, "type": "screen-rx", "format": "screen-rx", "objectives": ["To effectively screen new prescriptions to identify and describe any errors, omissions or concerns."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient."]}, {"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions."]}], "instructions": "Before entering the station, take one Candidate Answer Sheet and attach your barcode label in the space indicated. When the start signal sounds, enter the station and locate the drug reference materials and the five written prescriptions on the desk. There are five (5) WRITTEN PRESCRIPTIONS to assess for problems; some may have one or more problems that must be resolved before they can be processed and filled by a pharmacy technician. For each prescription, decide whether it is ready to be filled: if there are no problems, mark 'NO problem(s)'; if there are one or more problems, mark 'Specify problem(s)' and clearly write the specific problem(s) in the space provided. When the final signal sounds, stop writing immediately and leave your Candidate Answer Sheet face down on the desk for collection. You have 7 minutes to complete this station. Do not mark or write on the reference materials or written prescriptions in any way.", "sc": "You are screening five new written prescriptions before they are processed and filled by a pharmacy technician.", "ta": "Screen five written prescriptions and identify any problems.", "items": [{"label": "Prescription 1", "rx": "citalopram 20 mg, mitte 30 days, for Mr. Alan Brooks", "hasProblem": true, "detail": "no directions specified"}, {"label": "Prescription 2", "rx": "clotrimazole 1% cream, apply bid to affected area x 2 weeks for tinea pedis, mitte 30 g, for Ms. Priya Nair", "hasProblem": false, "detail": ""}, {"label": "Prescription 3", "rx": "prednisone, tab i po od x 5 days, mitte #5, for Mr. Derek Osei", "hasProblem": true, "detail": "no strength specified"}, {"label": "Prescription 4", "rx": "amoxicillin 500 mg, cap i tid x 10 days, for Ryan and Owen Fletcher (twins, age 8)", "hasProblem": true, "detail": "prescription cannot be written for more than one person"}, {"label": "Prescription 5", "rx": "sumatriptan 100 mg tab, take 1 tab at onset of migraine, mitte 9 tabs; and rizatriptan 10 mg ODT, take 1 tab at onset of migraine, mitte 6 tabs, both prn on the same order for Mrs. Carla Jimenez", "hasProblem": true, "detail": "therapeutic duplication - two triptans prescribed for the same indication"}], "printedMaterials": ["Monographs (booklet)", "Five Written Prescriptions"], "cl": ["Correctly identifies Prescription 1 as having a problem: no directions specified", "Correctly identifies Prescription 2 as having no problem", "Correctly identifies Prescription 3 as having a problem: no strength specified", "Correctly identifies Prescription 4 as having a problem: written for more than one person", "Correctly identifies Prescription 5 as having a problem: therapeutic duplication (two triptans)", "Uses precise, specific wording for each problem identified rather than vague statements", "Completes assessment of all five prescriptions within the allotted time"], "mn": "Read every field of a prescription (drug, strength, Sig, Mitte, patient) methodically in the same order each time so a missing element cannot slip past you under time pressure."}, {"id": "sr2", "ti": "Screening New Prescriptions: Pediatric Focus", "tl": 7, "type": "screen-rx", "format": "screen-rx", "objectives": ["To effectively screen new prescriptions to identify and describe any errors, omissions or concerns."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient."]}, {"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions."]}], "instructions": "Before entering the station, take one Candidate Answer Sheet and attach your barcode label in the space indicated. When the start signal sounds, enter the station and locate the drug reference materials and the five written prescriptions on the desk. There are five (5) WRITTEN PRESCRIPTIONS to assess for problems; some may have one or more problems that must be resolved before they can be processed and filled by a pharmacy technician. For each prescription, decide whether it is ready to be filled: if there are no problems, mark 'NO problem(s)'; if there are one or more problems, mark 'Specify problem(s)' and clearly write the specific problem(s) in the space provided. When the final signal sounds, stop writing immediately and leave your Candidate Answer Sheet face down on the desk for collection. You have 7 minutes to complete this station. Do not mark or write on the reference materials or written prescriptions in any way.", "sc": "You are screening five new written prescriptions for pediatric patients before they are processed and filled by a pharmacy technician.", "ta": "Screen five written pediatric prescriptions and identify any problems.", "items": [{"label": "Prescription 1", "rx": "tetracycline 250 mg, cap i qid x 7 days, for a 6-year-old child with a skin infection", "hasProblem": true, "detail": "medication not indicated for children under 8 (permanent tooth discolouration)"}, {"label": "Prescription 2", "rx": "amoxicillin 250 mg/5 mL suspension, give 5 mL tid x 10 days, mitte 150 mL, for a 4-year-old with acute otitis media", "hasProblem": false, "detail": ""}, {"label": "Prescription 3", "rx": "ibuprofen infant drops 40 mg/mL, give 1.25 mL q6h prn fever, mitte 30 mL, for a 3-month-old infant", "hasProblem": true, "detail": "medication not indicated for infants under 6 months of age"}, {"label": "Prescription 4", "rx": "salbutamol MDI, inhale 2 puffs q4h prn wheeze, mitte 1 inhaler, for a 7-year-old with asthma", "hasProblem": true, "detail": "no strength specified"}, {"label": "Prescription 5", "rx": "amoxicillin 250 mg, cap i tid x 7 days, for Emma and Ethan Sawyer (twins, age 5)", "hasProblem": true, "detail": "prescription cannot be written for more than one person"}], "printedMaterials": ["Monographs (booklet)", "Five Written Prescriptions"], "cl": ["Correctly identifies Prescription 1 as having a problem: drug not indicated for children under 8", "Correctly identifies Prescription 2 as having no problem", "Correctly identifies Prescription 3 as having a problem: not indicated under 6 months of age", "Correctly identifies Prescription 4 as having a problem: no strength specified", "Correctly identifies Prescription 5 as having a problem: written for more than one person", "Applies pediatric age-based contraindications correctly rather than relying on adult dosing norms", "Uses precise, specific wording for each problem identified"], "mn": "For pediatric prescriptions, always check the patient's age against the drug's minimum-age or weight-based restrictions before checking the dose itself."}, {"id": "sr3", "ti": "Screening New Prescriptions: Geriatric & Renal Focus", "tl": 7, "type": "screen-rx", "format": "screen-rx", "objectives": ["To effectively screen new prescriptions to identify and describe any errors, omissions or concerns."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient."]}, {"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions."]}], "instructions": "Before entering the station, take one Candidate Answer Sheet and attach your barcode label in the space indicated. When the start signal sounds, enter the station and locate the drug reference materials and the five written prescriptions on the desk. There are five (5) WRITTEN PRESCRIPTIONS to assess for problems; some may have one or more problems that must be resolved before they can be processed and filled by a pharmacy technician. For each prescription, decide whether it is ready to be filled: if there are no problems, mark 'NO problem(s)'; if there are one or more problems, mark 'Specify problem(s)' and clearly write the specific problem(s) in the space provided. When the final signal sounds, stop writing immediately and leave your Candidate Answer Sheet face down on the desk for collection. You have 7 minutes to complete this station. Do not mark or write on the reference materials or written prescriptions in any way.", "sc": "You are screening five new written prescriptions for older adult patients before they are processed and filled by a pharmacy technician.", "ta": "Screen five written prescriptions for older adults and identify any problems.", "items": [{"label": "Prescription 1", "rx": "metformin 500 mg, tab i bid, mitte 90 days, for Mr. Harold Weiss, 74 (chart notes eGFR 25 mL/min)", "hasProblem": true, "detail": "contraindicated in severe renal impairment (eGFR below 30)"}, {"label": "Prescription 2", "rx": "rosuvastatin 20 mg, tab i qhs, mitte 90 days, for Mrs. Doris Kaplan, 78 (normal renal function)", "hasProblem": false, "detail": ""}, {"label": "Prescription 3", "rx": "glyburide 5 mg, tab i bid, mitte 90 days, for Mr. Frank Iannucci, 82", "hasProblem": true, "detail": "inappropriate choice in the elderly - long-acting sulfonylurea carries high hypoglycemia risk"}, {"label": "Prescription 4", "rx": "digoxin, tab i od, mitte 90 days, for Mrs. Yvonne Trudeau, 80", "hasProblem": true, "detail": "no strength specified"}, {"label": "Prescription 5", "rx": "amoxicillin 500 mg, cap i tid x 7 days, for Mr. Tom Reyes and his wife Anna Reyes", "hasProblem": true, "detail": "prescription cannot be written for more than one person"}], "printedMaterials": ["Monographs (booklet)", "Five Written Prescriptions"], "cl": ["Correctly identifies Prescription 1 as having a problem: contraindicated at this level of renal impairment", "Correctly identifies Prescription 2 as having no problem", "Correctly identifies Prescription 3 as having a problem: high-risk choice for an elderly patient", "Correctly identifies Prescription 4 as having a problem: no strength specified", "Correctly identifies Prescription 5 as having a problem: written for more than one person", "Cross-references renal function and age-related risk against the drug chosen, not just the dose written", "Uses precise, specific wording for each problem identified"], "mn": "When a chart note gives renal function or age, treat it as a deliberate clue - screen every prescription against it before deciding there is no problem."}, {"id": "sr4", "ti": "Screening New Prescriptions: Controlled Substances & Duration", "tl": 7, "type": "screen-rx", "format": "screen-rx", "objectives": ["To effectively screen new prescriptions to identify and describe any errors, omissions or concerns."], "competencies": [{"code": "1A", "label": "Providing Care: Clinical Care", "elements": ["1.2 Assess the patient's health status and unique needs, goals, and preferences, in partnership with the patient."]}, {"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions."]}], "instructions": "Before entering the station, take one Candidate Answer Sheet and attach your barcode label in the space indicated. When the start signal sounds, enter the station and locate the drug reference materials and the five written prescriptions on the desk. There are five (5) WRITTEN PRESCRIPTIONS to assess for problems; some may have one or more problems that must be resolved before they can be processed and filled by a pharmacy technician. For each prescription, decide whether it is ready to be filled: if there are no problems, mark 'NO problem(s)'; if there are one or more problems, mark 'Specify problem(s)' and clearly write the specific problem(s) in the space provided. When the final signal sounds, stop writing immediately and leave your Candidate Answer Sheet face down on the desk for collection. You have 7 minutes to complete this station. Do not mark or write on the reference materials or written prescriptions in any way.", "sc": "You are screening five new written prescriptions involving controlled substances before they are processed and filled by a pharmacy technician.", "ta": "Screen five written prescriptions for controlled substances and identify any problems.", "items": [{"label": "Prescription 1", "rx": "hydromorphone 2 mg, tab i q4h prn pain, mitte 100 tabs, for Mr. Sam Delisle, 3 days post outpatient dental extraction", "hasProblem": true, "detail": "quantity excessive for a short-term acute pain indication"}, {"label": "Prescription 2", "rx": "zopiclone 7.5 mg, tab i hs prn insomnia, mitte 10 tabs, for Ms. Renata Kovac", "hasProblem": false, "detail": ""}, {"label": "Prescription 3", "rx": "oxycodone CR 20 mg, tab i q12h, mitte 60 tabs, refill x 3, for Mr. Bruce Halloran", "hasProblem": true, "detail": "refills not permitted for this controlled substance"}, {"label": "Prescription 4", "rx": "clonazepam 0.5 mg, mitte 30 tabs, for Mrs. Wanda Petrov", "hasProblem": true, "detail": "no directions specified"}, {"label": "Prescription 5", "rx": "fentanyl patch 25 mcg/hr, apply 1 patch q72h, mitte 5 patches, for Mr. Kyle Anderson, opioid-naive, acute ankle sprain", "hasProblem": true, "detail": "not appropriate for an opioid-naive patient with acute pain"}], "printedMaterials": ["Monographs (booklet)", "Five Written Prescriptions"], "cl": ["Correctly identifies Prescription 1 as having a problem: excessive quantity for acute pain", "Correctly identifies Prescription 2 as having no problem", "Correctly identifies Prescription 3 as having a problem: refills not permitted for a controlled substance", "Correctly identifies Prescription 4 as having a problem: no directions specified", "Correctly identifies Prescription 5 as having a problem: fentanyl patch inappropriate in an opioid-naive patient", "Applies controlled-substance quantity, duration, and refill rules correctly", "Uses precise, specific wording for each problem identified"], "mn": "For opioids and other controlled substances, check three things every time: is the quantity/duration appropriate for the stated indication, are refills allowed, and is the patient opioid-tolerant or opioid-naive."}, {"id": "cm1", "ti": "Checking Prepared Medications: Community Pharmacy", "tl": 7, "type": "check-meds", "format": "check-meds", "objectives": ["To check prepared medications and identify any corrections that must be made before the medications can be released."], "competencies": [{"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions.", "1.8 Verify the accuracy and quality of dispensed products and preparations.", "1.9 Release verified products and preparations."]}, {"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements."]}], "instructions": "Before you enter the station, take one Candidate Answer Sheet and attach a barcode label in the space provided. When the start signal sounds, enter the station and find the prepared medications and their corresponding written prescriptions on the desk/table. There are four (4) prepared medications to assess. For each one, determine whether it was prepared correctly: if it is correct, mark 'NO correction(s) required'; if a correction is required, mark 'Specify correction(s)' and clearly write out the specific correction(s) needed. Some items may require more than one correction. Assume all prescriptions were correctly written and that any drug therapy problems have already been resolved — your task is only to check the accuracy of preparation and labeling. Do NOT consider the omission of auxiliary labels. When the final signal sounds, stop writing immediately and turn your Candidate Answer Sheet over on the desk/table. You have 7 minutes to complete this station.", "sc": "You are checking four prepared medications against their written prescriptions before release to patients at a community pharmacy.", "ta": "Compare four prepared prescriptions against their written orders and specify any corrections needed.", "items": [{"label": "Prescription 1", "rx": "Amoxicillin 500 mg capsules.\nSig: Take 1 capsule three times daily for 10 days.\nMitte: 30 capsules.\nPatient: Marcus Delgado.\nPrescriber: Dr. R. Osei.", "prepared": "Amoxicillin 500 mg capsules.\nTake 1 capsule twice daily for 10 days.\nQty dispensed: 30 capsules.\nPatient: Marcus Delgado.", "hasProblem": true, "detail": "Change the directions on the label to 'Take 1 capsule three times daily for 10 days.'"}, {"label": "Prescription 2", "rx": "Atorvastatin 20 mg tablets.\nSig: Take 1 tablet at bedtime.\nMitte: 90 tablets (3-month supply).\nPatient: Priya Nair.\nPrescriber: Dr. L. Fontaine.", "prepared": "Atorvastatin 20 mg tablets.\nTake 1 tablet at bedtime.\nQty dispensed: 90 tablets.\nPatient: Priya Nair.", "hasProblem": false, "detail": ""}, {"label": "Prescription 3", "rx": "Metformin 500 mg tablets.\nSig: Take 1 tablet twice daily with meals.\nMitte: 60 tablets.\nPatient: Harold Whitfield.\nPrescriber: Dr. S. Boucher.", "prepared": "Metformin 500 mg tablets.\nTake 1 tablet twice daily with meals.\nQty dispensed: 100 tablets.\nPatient: Harold Whitfield.", "hasProblem": true, "detail": "Change the quantity dispensed on the label to 60 tablets and return the excess 40 tablets to stock."}, {"label": "Prescription 4", "rx": "Salbutamol HFA 100 mcg inhaler.\nSig: Inhale 2 puffs every 4-6 hours as needed for wheezing.\nMitte: 1 inhaler.\nPatient: Owen Kaplan.\nPrescriber: Dr. A. Mercier.", "prepared": "Salbutamol HFA 100 mcg inhaler.\nInhale 2 puffs every 4-6 hours as needed for wheezing.\nQty dispensed: 1 inhaler.\nPatient: Owen Kapler.", "hasProblem": true, "detail": "Change the patient name on the label to Owen Kaplan."}], "printedMaterials": ["Written prescriptions (four)", "Corresponding prepared medications (four)"], "cl": ["Correctly identifies that Prescription 1 requires a correction to the label directions (three times daily, not twice daily).", "Correctly identifies that Prescription 2 requires NO correction.", "Correctly identifies that Prescription 3 requires a correction to the quantity dispensed (60 tablets, not 100).", "Correctly identifies that Prescription 4 requires a correction to the patient name on the label (Owen Kaplan, not Owen Kapler).", "States the specific correction required for each item, not just a description of the problem.", "Does not mark a correction as required for an item that was prepared correctly."], "mn": "Work through each pair systematically in the same order every time — patient name, drug and strength, directions, and quantity — rather than skimming, since one correct-looking item is usually mixed in to catch candidates who assume every prescription has an error."}, {"id": "cm2", "ti": "Checking Prepared Medications: Hospital Outpatient Pharmacy", "tl": 7, "type": "check-meds", "format": "check-meds", "objectives": ["To check prepared medications and identify any corrections that must be made before the medications can be released."], "competencies": [{"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions.", "1.8 Verify the accuracy and quality of dispensed products and preparations.", "1.9 Release verified products and preparations."]}, {"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements."]}], "instructions": "Before you enter the station, take one Candidate Answer Sheet and attach a barcode label in the space provided. When the start signal sounds, enter the station and find the prepared medications and their corresponding written prescriptions on the desk/table. There are four (4) prepared medications to assess. For each one, determine whether it was prepared correctly: if it is correct, mark 'NO correction(s) required'; if a correction is required, mark 'Specify correction(s)' and clearly write out the specific correction(s) needed. Some items may require more than one correction. Assume all prescriptions were correctly written and that any drug therapy problems have already been resolved — your task is only to check the accuracy of preparation and labeling. Do NOT consider the omission of auxiliary labels. When the final signal sounds, stop writing immediately and turn your Candidate Answer Sheet over on the desk/table. You have 7 minutes to complete this station.", "sc": "You are checking four prepared medications against their written prescriptions before release to patients at a hospital outpatient pharmacy.", "ta": "Compare four prepared prescriptions against their written orders and specify any corrections needed.", "items": [{"label": "Prescription 1", "rx": "Levothyroxine 75 mcg tablets.\nSig: Take 1 tablet once daily in the morning on an empty stomach.\nMitte: 100 tablets.\nPatient: Grace Iwu.\nPrescriber: Dr. T. Nakamura.", "prepared": "Levothyroxine 50 mcg tablets.\nTake 1 tablet once daily in the morning on an empty stomach.\nQty dispensed: 100 tablets.\nPatient: Grace Iwu.", "hasProblem": true, "detail": "Change the strength dispensed on the label to Levothyroxine 75 mcg tablets (redispense with the correct strength product)."}, {"label": "Prescription 2", "rx": "Losartan 50 mg tablets.\nSig: Take 1 tablet once daily.\nMitte: 90 tablets.\nPatient: Desmond Kellerman.\nPrescriber: Dr. P. Aguilar.", "prepared": "Lorazepam 0.5 mg tablets.\nTake 1 tablet once daily.\nQty dispensed: 90 tablets.\nPatient: Desmond Kellerman.", "hasProblem": true, "detail": "The wrong drug was dispensed — relabel and dispense Losartan 50 mg tablets (not Lorazepam) as prescribed."}, {"label": "Prescription 3", "rx": "Rosuvastatin 10 mg tablets.\nSig: Take 1 tablet daily at bedtime.\nMitte: 90 tablets.\nPatient: Fatima Al-Sayed.\nPrescriber: Dr. C. Reyes.", "prepared": "Rosuvastatin 10 mg tablets.\nTake 1 tablet daily at bedtime.\nQty dispensed: 90 tablets.\nPatient: Fatima Al-Sayed.", "hasProblem": false, "detail": ""}, {"label": "Prescription 4", "rx": "Ramipril 5 mg capsules.\nSig: Take 1 capsule once daily in the morning.\nMitte: 30 capsules, 2 refills.\nPatient: Walter Osei-Bonsu.\nPrescriber: Dr. M. Tremblay.", "prepared": "Ramipril 5 mg capsules.\nTake 1 capsule once daily in the morning.\nQty dispensed: 30 capsules, 2 refills.\nPatient: Walter Osei-Bonsu.", "hasProblem": false, "detail": ""}], "printedMaterials": ["Written prescriptions (four)", "Corresponding prepared medications (four)"], "cl": ["Correctly identifies that Prescription 1 requires a correction to the strength dispensed (75 mcg, not 50 mcg).", "Correctly identifies that Prescription 2 was filled with the wrong drug entirely (Lorazepam instead of Losartan) and states the specific fix.", "Correctly identifies that Prescription 3 requires NO correction.", "Correctly identifies that Prescription 4 requires NO correction, including matching the refill count.", "States the specific correction required for each item, not just a description of the problem.", "Recognizes a look-alike/sound-alike drug name error even when the rest of the label (Sig, quantity, patient) matches."], "mn": "When two drug names look or sound alike, re-verify the full generic name and strength printed on the label against the prescription character by character — don't rely on the first few letters or a familiar overall label layout."}, {"id": "cm3", "ti": "Checking Prepared Medications: Compounding Pharmacy", "tl": 7, "type": "check-meds", "format": "check-meds", "objectives": ["To check prepared medications and identify any corrections that must be made before the medications can be released."], "competencies": [{"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions.", "1.8 Verify the accuracy and quality of dispensed products and preparations.", "1.9 Release verified products and preparations."]}, {"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements."]}], "instructions": "Before you enter the station, take one Candidate Answer Sheet and attach a barcode label in the space provided. When the start signal sounds, enter the station and find the prepared medications and their corresponding written prescriptions on the desk/table. There are four (4) prepared medications to assess. For each one, determine whether it was prepared correctly: if it is correct, mark 'NO correction(s) required'; if a correction is required, mark 'Specify correction(s)' and clearly write out the specific correction(s) needed. Some items may require more than one correction. Assume all prescriptions were correctly written and that any drug therapy problems have already been resolved — your task is only to check the accuracy of preparation and labeling. Do NOT consider the omission of auxiliary labels. When the final signal sounds, stop writing immediately and turn your Candidate Answer Sheet over on the desk/table. You have 7 minutes to complete this station.", "sc": "You are checking four prepared medications, including two compounded preparations, against their written prescriptions before release to patients.", "ta": "Compare four prepared prescriptions, including compounded items, against their written orders and specify any corrections needed.", "items": [{"label": "Prescription 1", "rx": "Compounded Omeprazole Oral Suspension 2 mg/mL.\nSig: Give 5 mL (10 mg) by mouth once daily before breakfast.\nMitte: 100 mL.\nPatient: Lily Bergeron.\nPrescriber: Dr. K. Whitmore.", "prepared": "Compounded Omeprazole Oral Suspension.\nGive 5 mL (10 mg) by mouth once daily before breakfast.\nQty dispensed: 40 mL (final dilution to volume with vehicle was not completed, yielding approximately 4 mg/mL).\nPatient: Lily Bergeron.", "hasProblem": true, "detail": "Recompound the suspension to the correct final concentration of 2 mg/mL by bringing it to its full final volume of 100 mL with the compounding vehicle."}, {"label": "Prescription 2", "rx": "Cholestyramine powder for oral suspension.\nSig: Mix 1 packet (4 g) in water or juice, take once daily before breakfast.\nMitte: 30 packets.\nPatient: Noreen Faulkner.\nPrescriber: Dr. B. Bertrand.", "prepared": "Cholestyramine powder for oral suspension.\nMix 1 packet (4 g) in water or juice, take once daily before breakfast.\nQty dispensed: 14 packets.\nPatient: Noreen Faulkner.", "hasProblem": true, "detail": "Change the quantity dispensed on the label to 30 packets and dispense the remaining 16 packets."}, {"label": "Prescription 3", "rx": "Compounded Magic Mouthwash (equal parts diphenhydramine, lidocaine, and aluminum-magnesium hydroxide suspension).\nSig: Swish and spit 10 mL four times daily as needed for mouth pain.\nMitte: 240 mL.\nPatient: Terrence Okafor.\nPrescriber: Dr. V. Sabharwal.", "prepared": "Compounded Magic Mouthwash (equal parts diphenhydramine, lidocaine, and aluminum-magnesium hydroxide suspension).\nSwish and spit 10 mL four times daily as needed for mouth pain.\nQty dispensed: 240 mL.\nPatient: Terrence Okafor.", "hasProblem": false, "detail": ""}, {"label": "Prescription 4", "rx": "Compounded Betamethasone Valerate 0.1% Cream in Sorbolene base.\nSig: Apply a thin layer to the affected area twice daily.\nMitte: 100 g.\nPatient: Simone Achterberg.\nPrescriber: Dr. E. Popescu.", "prepared": "Compounded Betamethasone Valerate 0.1% Cream in Sorbolene base.\nApply a thin layer to the affected area twice daily.\nQty dispensed: 100 g.\nPatient: Simone Albrecht.", "hasProblem": true, "detail": "Change the patient name on the label to Simone Achterberg."}], "printedMaterials": ["Written prescriptions (four)", "Corresponding prepared medications (four)", "Compounding worksheets (where applicable)"], "cl": ["Correctly identifies that Prescription 1 was not brought to its correct final volume/concentration and states the specific recompounding fix.", "Correctly identifies that Prescription 2 requires a correction to the quantity dispensed (30 packets, not 14).", "Correctly identifies that Prescription 3 requires NO correction.", "Correctly identifies that Prescription 4 requires a correction to the patient name on the label (Simone Achterberg, not Simone Albrecht).", "States the specific correction required for each item, not just a description of the problem.", "Applies the same level of scrutiny to compounded preparations as to commercially manufactured products."], "mn": "For compounded items, check the final volume or weight against what the concentration requires — a short-filled base or vehicle is a common way a compound ends up at the wrong concentration even though the ingredients themselves were correct."}, {"id": "cm4", "ti": "Checking Prepared Medications: Long-Term Care Pharmacy", "tl": 7, "type": "check-meds", "format": "check-meds", "objectives": ["To check prepared medications and identify any corrections that must be made before the medications can be released."], "competencies": [{"code": "1B", "label": "Providing Care: Distribution", "elements": ["1.6 Review and process prescriptions.", "1.8 Verify the accuracy and quality of dispensed products and preparations.", "1.9 Release verified products and preparations."]}, {"code": "5", "label": "Professionalism", "elements": ["5.1 Adhere to relevant legislative and regulatory requirements."]}], "instructions": "Before you enter the station, take one Candidate Answer Sheet and attach a barcode label in the space provided. When the start signal sounds, enter the station and find the prepared medications and their corresponding written prescriptions on the desk/table. There are four (4) prepared medications to assess. For each one, determine whether it was prepared correctly: if it is correct, mark 'NO correction(s) required'; if a correction is required, mark 'Specify correction(s)' and clearly write out the specific correction(s) needed. Some items may require more than one correction. Assume all prescriptions were correctly written and that any drug therapy problems have already been resolved — your task is only to check the accuracy of preparation and labeling. Do NOT consider the omission of auxiliary labels. When the final signal sounds, stop writing immediately and turn your Candidate Answer Sheet over on the desk/table. You have 7 minutes to complete this station.", "sc": "You are checking four prepared medications against their written prescriptions before release to a long-term care unit.", "ta": "Compare four prepared prescriptions against their written orders and specify any corrections needed.", "items": [{"label": "Prescription 1", "rx": "Warfarin 3 mg tablets.\nSig: Take 1 tablet once daily in the evening.\nMitte: 30 tablets.\nPatient: Beatrice Yun.\nPrescriber: Dr. G. Laurin.", "prepared": "Warfarin 3 mg tablets.\nTake 1 tablet twice daily in the evening.\nQty dispensed: 30 tablets.\nPatient: Beatrice Yun.", "hasProblem": true, "detail": "Change the directions on the label to 'Take 1 tablet once daily in the evening.'"}, {"label": "Prescription 2", "rx": "Clonazepam 0.5 mg tablets.\nSig: Take 1 tablet at bedtime as needed for restless legs.\nMitte: 30 tablets.\nPatient: Arthur Deschamps.\nPrescriber: Dr. F. Nkurunziza.", "prepared": "Clonidine 0.1 mg tablets.\nTake 1 tablet at bedtime as needed for restless legs.\nQty dispensed: 30 tablets.\nPatient: Arthur Deschamps.", "hasProblem": true, "detail": "The wrong drug was dispensed — relabel and dispense Clonazepam 0.5 mg tablets (not Clonidine) as prescribed."}, {"label": "Prescription 3", "rx": "Furosemide oral solution 10 mg/mL.\nSig: Give 4 mL (40 mg) by mouth once daily in the morning.\nMitte: 150 mL.\nPatient: Herbert Coyle.\nPrescriber: Dr. J. Vandenberg.", "prepared": "Furosemide oral solution 2 mg/mL.\nGive 4 mL (40 mg) by mouth once daily in the morning.\nQty dispensed: 150 mL.\nPatient: Herbert Coyle.", "hasProblem": true, "detail": "Change the concentration on the label and product to Furosemide oral solution 10 mg/mL (dispense the correct concentration product)."}, {"label": "Prescription 4", "rx": "Donepezil 10 mg tablets.\nSig: Take 1 tablet once daily at bedtime.\nMitte: 30 tablets.\nPatient: Louisa Fennimore.\nPrescriber: Dr. R. Okonkwo.", "prepared": "Donepezil 10 mg tablets.\nTake 1 tablet once daily at bedtime.\nQty dispensed: 30 tablets.\nPatient: Louisa Fennimore.", "hasProblem": false, "detail": ""}], "printedMaterials": ["Written prescriptions (four)", "Corresponding prepared medications (four)"], "cl": ["Correctly identifies that Prescription 1 requires a correction to the label directions (once daily, not twice daily).", "Correctly identifies that Prescription 2 was filled with the wrong drug entirely (Clonidine instead of Clonazepam) and states the specific fix.", "Correctly identifies that Prescription 3 requires a correction to the concentration dispensed (10 mg/mL, not 2 mg/mL).", "Correctly identifies that Prescription 4 requires NO correction.", "States the specific correction required for each item, not just a description of the problem.", "Notices that a matching total dose (e.g., 4 mL = 40 mg on the label) can mask an underlying concentration error and checks the concentration itself, not just the arithmetic."], "mn": "A label can show the 'right' total dose and still be wrong — always check strength/concentration as its own field against the prescription, since a volume can be recalculated to match an incorrect concentration and still look correct at a glance."}];
